  .erp-root *,.erp-root 
  *::before,.erp-root 
  *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  .erp-root ::selection {
    background: var(--primary);
    color: var(--primary-foreground);
  }

  .erp-root {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
    -moz-text-size-adjust: 100%;
    text-size-adjust: 100%;
    overscroll-behavior: none;
  }

  html:has(.erp-root) {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
    -moz-text-size-adjust: 100%;
    text-size-adjust: 100%;
    overscroll-behavior: none;
  }

  /* Offset anchors for fixed nav + audience bar — see --scroll-stack in tokens.css. */
  .erp-root [id] {
    scroll-margin-top: var(--scroll-stack);
  }

  .erp-root {
    font-family: var(--font-body);
    font-size: var(--text-base);
    line-height: 1.6;
    color: var(--foreground);
    background-color: var(--background);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow-x: hidden;
    position: relative;
  }

  body:has(.erp-root) {
    font-family: var(--font-body);
    font-size: var(--text-base);
    line-height: 1.6;
    color: var(--foreground);
    background-color: var(--background);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow-x: hidden;
    position: relative;
  }

  /* EB Garamond italic reads thin at hero sizes against brutalist uppercase
     headlines. Bump the utility to 600 (Semi-Bold) so every italic
     pull-quote has real presence without losing humanist character. */
  .erp-root .font-serif {
    font-weight: 600;
  }

  .erp-root h1,.erp-root 
  h2,.erp-root 
  h3,.erp-root 
  h4,.erp-root 
  h5,.erp-root 
  h6 {
    font-family: var(--font-heading);
    font-weight: 500;
    line-height: 1.1;
    color: var(--foreground);
    letter-spacing: 0;
    text-wrap: balance;
  }
  .erp-root h1 {
    font-size: var(--text-5xl);
  }
  .erp-root h2 {
    font-size: var(--text-4xl);
  }
  .erp-root h3 {
    font-size: var(--text-3xl);
  }
  .erp-root h4 {
    font-size: var(--text-2xl);
  }

  .erp-root p {
    margin-bottom: var(--space-4);
    text-wrap: pretty;
  }

  .erp-root a {
    color: var(--foreground);
    text-decoration: none;
    transition: color var(--duration-fast) var(--ease-standard);
  }
  .erp-root a:hover {
    color: var(--primary);
  }

  .erp-root code,.erp-root 
  pre,.erp-root 
  kbd,.erp-root 
  samp {
    font-family: var(--font-mono);
    font-size: 0.9em;
  }
  .erp-root pre {
    overflow-x: auto;
    padding: var(--space-4);
    background: var(--surface-container);
  }
  .erp-root img,.erp-root 
  svg,.erp-root 
  video {
    display: block;
    max-width: 100%;
    height: auto;
  }
  .erp-root button,.erp-root 
  input,.erp-root 
  select,.erp-root 
  textarea {
    font: inherit;
    color: inherit;
  }
  .erp-root button {
    cursor: pointer;
  }
  .erp-root :focus-visible {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
  }

  .erp-root .skip-link {
    position: absolute;
    top: -100%;
    left: max(var(--space-4), var(--viewport-safe-left));
    padding: var(--space-2) var(--space-4);
    background: var(--primary);
    color: var(--primary-foreground);
    z-index: var(--z-skip);
    transition: top var(--duration-fast) var(--ease-standard);
  }
  .erp-root .skip-link:focus {
    top: var(--space-2);
  }

  .erp-root ::-webkit-scrollbar {
    width: 4px;
  }
  .erp-root ::-webkit-scrollbar-track {
    background: var(--background);
  }
  .erp-root ::-webkit-scrollbar-thumb {
    background: var(--foreground);
  }
  .erp-root ::-webkit-scrollbar-thumb:hover {
    background: var(--primary);
  }

  /* Code-block scrollbars — sleeker than Chrome's default ~14px chunk
     but chunkier than the page body's 4px hairline above. The beige-500
     thumb (mid gold, L 60) sits on a transparent track and reads with
     strong contrast against either light (--dark = beige-100, L 96.5)
     or dark (--dark = beige-800, L 22) code-panel backgrounds — same
     token value in both themes, so the bar reads consistently warm
     across light and dark mode.
     Targets <pre> directly when it is the scroll container (ops, modal,
     scenario-grid), and any element whose direct child is <pre> (the
     wrapping <div class="overflow-x-auto"> pattern in proto/sdk-01,
     byoa, proto/discovery, vcs/diff-view, etc.). `.overflow-x-auto`
     and `.scroll-thin` extend the same treatment to tables and other
     narrow-viewport scrollers whose contents aren't a <pre> (e.g.
     pricing matrices and proto/§09 cost-attribution grid table).
     Pseudo-element rules only render when the element actually
     overflows, so non-scrolling consumers are unaffected. */
  .erp-root pre::-webkit-scrollbar,.erp-root 
  :has(> pre)::-webkit-scrollbar,.erp-root 
  .overflow-x-auto::-webkit-scrollbar,.erp-root 
  .scroll-thin::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  .erp-root pre::-webkit-scrollbar-track,.erp-root 
  :has(> pre)::-webkit-scrollbar-track,.erp-root 
  .overflow-x-auto::-webkit-scrollbar-track,.erp-root 
  .scroll-thin::-webkit-scrollbar-track {
    background: transparent;
  }
  .erp-root pre::-webkit-scrollbar-thumb,.erp-root 
  :has(> pre)::-webkit-scrollbar-thumb,.erp-root 
  .overflow-x-auto::-webkit-scrollbar-thumb,.erp-root 
  .scroll-thin::-webkit-scrollbar-thumb {
    background: var(--beige-500);
  }
  .erp-root pre::-webkit-scrollbar-thumb:hover,.erp-root 
  :has(> pre)::-webkit-scrollbar-thumb:hover,.erp-root 
  .overflow-x-auto::-webkit-scrollbar-thumb:hover,.erp-root 
  .scroll-thin::-webkit-scrollbar-thumb:hover {
    background: var(--beige-600);
  }
  /* Firefox — `thin` is ~8–10px in Gecko, similar perceived weight. */
  .erp-root pre,.erp-root 
  :has(> pre),.erp-root 
  .overflow-x-auto,.erp-root 
  .scroll-thin {
    scrollbar-width: thin;
    scrollbar-color: var(--beige-500) transparent;
  }

  /* Content width cap — section backgrounds bleed full, content is capped.
     Pages with .main--full-bleed skip the cap entirely. */
  .erp-root #main-content:not(.main--full-bleed) > section > *,.erp-root 
  #main-content:not(.main--full-bleed) > header > *,.erp-root 
  #main-content:not(.main--full-bleed) > div > * {
    max-width: 90rem;
    margin-inline: auto;
  }
}

@layer components {
  /* -- Live-dashboard app preview boundary -------------------------------- *
   * Embedded SaaS-style product preview rendered inside the ERP + CRM
   * marketing pages. The `.live-dashboard` scope is an explicit documented
   * design boundary (DESIGN.md §7 → "Live-Dashboard Preview Boundary"):
   * rounded surfaces, soft shadows, and the `--ld-*` token namespace are
   * allowed *inside* `.live-dashboard` but must not leak outside.
   * Migrated from src/_includes/sections/shared/live-dashboard-style.njk
   * per AGENTS.md rule #11.
   * ───────────────────────────────────────────────────────────────────── */

  /* Local token aliases + outer frame — same token values as
     apps/web-work's tokens.css. Defined inside the .live-dashboard
     scope so they don't bleed into the rest of the (brutalist)
     marketing page. */
  .erp-root .live-dashboard {
    --ld-bg: oklch(99% 0.005 78);
    --ld-fg: oklch(14.1% 0.005 285.823);
    --ld-card: oklch(99% 0.005 78);
    --ld-muted: oklch(96.7% 0.001 286.375);
    --ld-muted-fg: oklch(55.2% 0.016 285.938);
    --ld-accent: oklch(96.7% 0.001 286.375);
    --ld-border: oklch(92% 0.004 286.32);
    --ld-sidebar: oklch(98.5% 0.005 78);
    --ld-brand: oklch(55% 0.21 25);
    --ld-radius: 8px;
    --ld-radius-card: 12px;
    --ld-ring-card: 0 0 0 1px oklch(14.1% 0.005 285.823 / 0.08);
    --ld-shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.04);

    /* Outer frame — embedded SaaS preview look */
    border-radius: 14px;
    background: var(--ld-bg);
    box-shadow:
      0 0 0 1px var(--ld-border),
      0 1px 3px 0 rgb(15 23 42 / 0.04),
      0 8px 24px -6px rgb(15 23 42 / 0.08),
      0 24px 64px -16px rgb(15 23 42 / 0.1);
    overflow: hidden;
    transform: translateY(0) scale(1);
    transition:
      transform 400ms cubic-bezier(0.2, 0, 0.1, 1),
      box-shadow 400ms cubic-bezier(0.2, 0, 0.1, 1);
    will-change: transform;
    color: var(--ld-fg);
    font-family: var(--font-body);
    font-size: 14px;
    line-height: 20px;
  }
  .erp-root .live-dashboard:hover {
    transform: translateY(-4px) scale(1.012);
    box-shadow:
