  /* -- Proto apex navigation -------------------------------------
     Markup lives in @lab/chrome's nav-apex-01 variant; styles stay local
     because this visual treatment is specific to the apex site. */
  .erp-root .proto-nav {
    --tacet-nav-bg: url('/assets/assets/images/proto/gradient-navbar-bg.png');
    --tacet-nav-ink: var(--foreground);
    --tacet-nav-muted: var(--text-m);
    --tacet-nav-width: min(calc((100vw - 2rem) * 0.9), 25rem);
    --tacet-nav-width-scrolled: min(calc((100vw - 2rem) * 0.88), 25rem);
    --tacet-nav-pill-bg: rgb(40 35 32 / 0.88);
    --tacet-nav-pill-ink: rgb(255 252 246);
    --tacet-nav-panel: color-mix(in oklab, var(--background), transparent 72%);
    --tacet-nav-panel-rest: color-mix(in oklab, var(--background), transparent 80%);
    --tacet-nav-panel-scrolled: color-mix(in oklab, var(--background), transparent 40%);
    --tacet-nav-border: color-mix(in oklab, white, transparent 42%);
    --tacet-nav-border-rest: color-mix(in oklab, white, transparent 34%);
    --tacet-nav-border-scrolled: color-mix(in oklab, var(--foreground), transparent 80%);
    --tacet-nav-shadow-scrolled:
      0 8px 20px -5px rgb(0 0 0 / 0.1), 0 4px 10px -5px rgb(0 0 0 / 0.08);
    --tacet-nav-inset-top: var(--space-2);
    --tacet-nav-notice-content-block-size: 2.125rem;
    --tacet-nav-notice-block-size: calc(
      var(--tacet-nav-notice-content-block-size) + var(--border-width-sm) + var(--border-width-sm)
    );
    position: fixed;
    inset: 0 0 auto;
    z-index: 80;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0;
    padding-block: var(--tacet-nav-inset-top) 0;
    padding-left: max(1rem, var(--viewport-safe-left));
    padding-right: max(1rem, var(--viewport-safe-right));
    pointer-events: none;
  }

  .erp-root .proto-nav__wash {
    position: absolute;
    inset: 0 0 auto;
    height: 38rem;
    z-index: -1;
    pointer-events: none;
    background-image: var(--tacet-nav-bg);
    background-position: top center;
    background-size: cover;
    opacity: 0;
    transition: opacity var(--duration-normal) var(--ease-standard);
  }

  .erp-root .proto-nav[data-scrolled='true'] .proto-nav__wash {
    opacity: 0;
  }

  .erp-root .proto-nav__notice {
    position: relative;
    z-index: 2;
    pointer-events: auto;
    display: flex;
    max-width: min(90vw, 42rem);
    min-height: var(--tacet-nav-notice-block-size);
    align-items: center;
    justify-content: center;
    border-radius: 0.5rem 0.5rem 0 0;
    border: 1px solid rgb(255 255 255 / 0.16);
    background: var(--tacet-nav-pill-bg);
    color: var(--tacet-nav-pill-ink);
    font-family: var(--font-body);
    font-size: 0.8125rem;
    font-weight: 650;
    line-height: 1;
    transition:
      background var(--duration-normal) var(--ease-standard),
      border-color var(--duration-normal) var(--ease-standard),
      border-radius var(--duration-normal) var(--ease-standard),
      transform var(--duration-normal) var(--ease-standard);
    backdrop-filter: blur(16px) saturate(150%);
  }

  .erp-root .proto-nav__audience-slot {
    width: min(90vw, 42rem);
    min-height: var(--tacet-nav-notice-block-size);
    flex: 0 0 auto;
    pointer-events: none;
  }

  .erp-root .proto-nav[data-scrolled='true'] .proto-nav__notice {
    border-bottom-color: transparent;
    transform: translateY(0);
  }

  .erp-root .proto-nav__notice-inner {
    display: inline-flex;
    min-height: var(--tacet-nav-notice-content-block-size);
    align-items: center;
    gap: 0.625rem;
    padding: 0 0.95rem;
    color: inherit;
  }

  .erp-root .proto-nav__notice-link {
    display: inline-flex;
    min-height: var(--tacet-nav-notice-content-block-size);
    align-items: center;
    padding: 0;
    border: 0;
    background: transparent;
    color: inherit;
    cursor: pointer;
    font: inherit;
    text-decoration: none;
  }

