      box-shadow var(--duration-normal) var(--ease-standard),
      transform var(--duration-normal) var(--ease-standard);
  }
  .erp-root .card:hover {
    box-shadow: var(--shadow-4);
    transform: translate(-2px, -2px);
  }
  .erp-root .card--outlined {
    box-shadow: none;
    border: 1px solid var(--border);
  }
  .erp-root .card--filled {
    background: var(--surface-container-highest);
    border: none;
    box-shadow: none;
  }

  /* -- Angular clip shapes (aTsh signature) -------------------------------- */
  .erp-root .btn-angular {
    clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%);
  }
  .erp-root .card-angular {
    clip-path: polygon(0 0, 100% 0, 100% calc(100% - 24px), calc(100% - 24px) 100%, 0 100%);
  }

  /* -- Button --------------------------------------------------------------- */
  .erp-root .btn {
    --btn-face: var(--beige-50);
    --btn-fill-hover: var(--beige-100);
    --btn-text: var(--ink-deep);
    --btn-border: var(--beige-300);
    --btn-text-hover: var(--ink-deep);
    --btn-border-hover: var(--ink-deep);
    --btn-rail: var(--tacet-orange-on-light);
    --btn-rail-hover: var(--tacet-orange-on-light);

    position: relative;
    isolation: isolate;
    overflow: hidden;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
    font-family: var(--font-body);
    font-weight: 600;
    font-size: var(--text-xs);
    line-height: 1;
    padding: var(--space-3) var(--space-8);
    border: 1px solid var(--btn-border);
    border-radius: 0;
    background: var(--btn-face);
    box-shadow: none;
    color: var(--btn-text);
    cursor: pointer;
    text-transform: uppercase;
    letter-spacing: 0.13em;
    text-decoration: none;
    transition:
      color var(--duration-fast) var(--ease-standard),
      border-color var(--duration-fast) var(--ease-standard),
      transform var(--duration-fast) var(--ease-standard);
  }

  .erp-root .btn::before {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--btn-fill-hover);
    pointer-events: none;
    z-index: -1;
    transform: scaleX(0);
    transform-origin: left;
    transition: transform var(--duration-fast) var(--ease-decelerate);
  }

  .erp-root .btn::after {
    content: '';
    display: block;
    position: absolute;
    right: -1px;
    bottom: -1px;
    left: -1px;
    height: 2px;
    background: var(--btn-rail);
    pointer-events: none;
    z-index: 1;
    transform: scaleX(1);
    transform-origin: left;
    transition:
      background var(--duration-fast) var(--ease-standard),
      transform var(--duration-fast) var(--ease-standard);
  }

  .erp-root .btn:hover {
    border-color: var(--btn-border-hover);
    color: var(--btn-text-hover);
  }

  .erp-root .btn:hover::before {
    transform: scaleX(1);
  }

  .erp-root .btn:hover::after {
    background: var(--btn-rail-hover);
    transform: scaleX(1);
  }

  .erp-root .btn:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 3px;
  }

  .erp-root .btn:active {
    transform: translateY(1px) scale(0.99);
    transition-duration: 70ms;
  }

  .erp-root .btn--primary {
    --btn-face: var(--ink-deep);
    --btn-fill-hover: var(--tacet-orange-on-light);
    --btn-text: var(--beige-50);
    --btn-border: var(--tacet-orange-on-light);
    --btn-text-hover: var(--beige-50);
    --btn-border-hover: var(--ink-deep);
    --btn-rail: var(--tacet-orange-on-light);
    --btn-rail-hover: var(--ink-deep);
  }

  .erp-root .btn--secondary {
    --btn-face: var(--background);
    --btn-fill-hover: color-mix(
      in oklab,
      var(--surface-container),
      var(--tacet-orange-on-light) 12%
    );
    --btn-text: var(--foreground);
    --btn-border: var(--foreground);
    --btn-text-hover: var(--foreground);
    --btn-border-hover: var(--tacet-orange-on-light);
    --btn-rail: var(--tacet-orange-on-light);
    --btn-rail-hover: var(--tacet-orange-on-light);
  }

  .erp-root .btn--outline {
    --btn-face: var(--background);
    --btn-fill-hover: var(--surface-dim);
    --btn-text: var(--foreground);
    --btn-border: var(--border);
    --btn-text-hover: var(--foreground);
    --btn-border-hover: var(--foreground);
    --btn-rail: var(--border);
    --btn-rail-hover: var(--foreground);
  }

  .erp-root .btn--ghost {
    --btn-face: transparent;
    --btn-fill-hover: transparent;
    --btn-text: var(--text-m);
    --btn-border: transparent;
    --btn-text-hover: var(--foreground);
    --btn-border-hover: transparent;
    --btn-rail: var(--tacet-orange-on-light);
    --btn-rail-hover: var(--tacet-orange-on-light);

    overflow: visible;
    padding-inline: 0.1rem;
    border: 0;
    background: transparent;
    box-shadow: inset 0 -1px 0 var(--border);
  }

  .erp-root .btn--ghost::before {
    display: none;
  }

  .erp-root .btn--ghost::after {
    right: 0;
    bottom: 0;
    left: 0;
    transform: scaleX(0);
  }

  .erp-root .btn--ghost:hover::after {
    transform: scaleX(1);
  }

  .erp-root .btn--tech,.erp-root 
  .btn--tech-primary,.erp-root 
  .btn--tech-secondary,.erp-root 
  .btn--tech-ghost {
    --btn-frame: var(--tacet-orange);
    --btn-frame-hover: var(--ink-deep);
    --btn-frame-width: 3px;
    --btn-corner-size: 0.875rem;
    overflow: visible;
    border: var(--btn-frame-width) solid var(--btn-frame);
    letter-spacing: 0.18em;
    box-shadow: none;
  }

  .erp-root .btn--tech::before,.erp-root 
  .btn--tech-primary::before,.erp-root 
  .btn--tech-secondary::before,.erp-root 
  .btn--tech-ghost::before {
    display: none;
  }

  .erp-root .btn--tech::after,.erp-root 
  .btn--tech-primary::after,.erp-root 
  .btn--tech-secondary::after,.erp-root 
  .btn--tech-ghost::after {
    content: '';
    display: block;
    position: absolute;
    top: calc(-1 * var(--btn-frame-width));
    right: calc(-1 * var(--btn-frame-width));
    bottom: auto;
    left: auto;
    width: var(--btn-corner-size);
    height: var(--btn-corner-size);
    background: var(--btn-frame);
    pointer-events: none;
    transform: none;
    transition: background var(--duration-fast) var(--ease-standard);
  }

  .erp-root .btn--tech:hover,.erp-root 
  .btn--tech-primary:hover,.erp-root 
  .btn--tech-secondary:hover,.erp-root 
  .btn--tech-ghost:hover {
    background: var(--btn-face-hover);
    border-color: var(--btn-frame-hover);
    color: var(--btn-text-hover);
    box-shadow: none;
  }

  .erp-root .btn--tech:hover::after,.erp-root 
  .btn--tech-primary:hover::after,.erp-root 
  .btn--tech-secondary:hover::after,.erp-root 
  .btn--tech-ghost:hover::after {
    background: var(--btn-frame-hover);
  }

  .erp-root .btn--tech-primary {
    --btn-face: var(--ink-deep);
    --btn-text: var(--beige-50);
    --btn-face-hover: var(--tacet-orange-on-light);
    --btn-text-hover: var(--beige-50);
  }

  .erp-root .btn--tech-secondary {
    --btn-face: var(--beige-50);
    --btn-text: var(--ink-deep);
    --btn-face-hover: var(--beige-200);
    --btn-text-hover: var(--tacet-orange-on-light);
  }

  .erp-root .btn--tech-ghost {
    --btn-face: transparent;
    --btn-text: var(--text-m);
    --btn-frame: transparent;
    --btn-face-hover: transparent;
    --btn-text-hover: var(--foreground);
    --btn-frame-hover: transparent;
    padding-inline: 0;
    border: 0;
    background: transparent;
  }

  .erp-root .btn--tech-ghost::after {
    display: none;
  }

  .erp-root .btn--destructive {
    --btn-face: var(--destructive);
    --btn-fill-hover: var(--red-on-light);
    --btn-text: var(--primary-foreground);
    --btn-border: var(--foreground);
    --btn-text-hover: var(--primary-foreground);
    --btn-border-hover: var(--red);
    --btn-rail: var(--red);
    --btn-rail-hover: var(--foreground);
  }

  .erp-root .btn:disabled,.erp-root 
  .btn[aria-disabled='true'] {
    --btn-face: var(--surface-dim);
    --btn-fill-hover: var(--surface-dim);
    --btn-text: var(--text-m);
    --btn-border: var(--border);
    --btn-border-hover: var(--border);
    --btn-rail: var(--border);
    --btn-rail-hover: var(--border);

    opacity: 0.72;
    cursor: not-allowed;
    pointer-events: none;
  }

  .erp-root .btn--loading {
    cursor: progress;
    pointer-events: none;
  }
  .erp-root .btn__icon,.erp-root 
  .btn__spinner {
    width: 1em;
    height: 1em;
    flex-shrink: 0;
  }
  .erp-root .btn__icon,.erp-root 
  .btn > svg:not(.btn__spinner) {
    transition: transform var(--duration-fast) var(--ease-standard);
  }
  .erp-root .btn:hover .btn__icon,.erp-root 
  .btn:hover > svg:not(.btn__spinner) {
    transform: translateX(0.125rem);
  }
  .erp-root .btn__spinner {
    transform-origin: center;
    animation: btn-spin var(--duration-slower) linear infinite;
  }
  @keyframes btn-spin {
    to {
      transform: rotate(360deg);
    }
  }
  @media (prefers-reduced-motion: reduce) {
    .erp-root .btn,.erp-root 
    .btn::before,.erp-root 
    .btn::after,.erp-root 
    .btn__icon,.erp-root 
    .btn > svg {
      transition-duration: 0.01ms !important;
    }

    .erp-root .btn:hover,.erp-root 
    .btn:active,.erp-root 
    .btn:hover .btn__icon,.erp-root 
    .btn:hover > svg {
      transform: none;
    }

    .erp-root .btn__spinner {
      animation: none;
    }
  }

  .erp-root .btn--xs {
    font-size: 0.625rem;
    /* Padding bumped from space-1/3 (4×12) so total height meets WCAG 2.2
       SC 2.5.8 (24×24 minimum) — 10px font + 16px y-padding ≈ 26px tall. */
    padding: var(--space-2) var(--space-3);
  }
  .erp-root .btn--sm {
    font-size: var(--text-xs);
    padding: var(--space-2) var(--space-4);
