  }
  .erp-root .group:hover .hover-layer {
    transform: translateY(0);
  }

  /* -- Noise overlay (aTsh texture) ---------------------------------------- */
  .erp-root .bg-noise {
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  }

  /* -- Marquee ------------------------------------------------------------- */
  .erp-root .marquee-container {
    overflow: hidden;
    white-space: nowrap;
    width: 100%;
    display: flex;
  }
  .erp-root .marquee-content {
    display: flex;
    flex-shrink: 0;
    min-width: 100%;
    animation: marquee 25s linear infinite;
  }
  .erp-root .marquee-content > * {
    flex-shrink: 0;
  }
  @keyframes marquee {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }

  /* -- Section clear (removes layout padding for full-bleed sections) ------ */
  .erp-root .section-clear {
    margin-inline: calc(var(--space-4) * -1);
  }
  @media (min-width: 640px) {
    .erp-root .section-clear {
      margin-inline: calc(var(--space-6) * -1);
    }
  }
  @media (min-width: 1024px) {
    .erp-root .section-clear {
      margin-inline: calc(var(--space-8) * -1);
    }
  }

  /* -- Observe: reveal animation base states ------------------------------- */
  .erp-root [data-observe='reveal'],.erp-root 
  [data-observe='reveal-up'],.erp-root 
  [data-observe~='reveal'],.erp-root 
  [data-observe~='reveal-up'] {
    opacity: 1;
    transform: none;
  }
  .erp-root [data-observe='reveal'].observed,.erp-root 
  [data-observe='reveal-up'].observed,.erp-root 
  [data-observe~='reveal'].observed,.erp-root 
  [data-observe~='reveal-up'].observed {
    animation: tacet-observed-reveal var(--duration-slow) var(--ease-decelerate) both;
    animation-delay: calc(var(--stagger-index, 0) * var(--stagger-fast, 80ms));
  }

  @keyframes tacet-observed-reveal {
    from {
      opacity: 0.82;
      transform: translateY(1rem);
    }

    to {
      opacity: 1;
      transform: none;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .erp-root [data-observe='reveal'].observed,.erp-root 
    [data-observe='reveal-up'].observed,.erp-root 
    [data-observe~='reveal'].observed,.erp-root 
    [data-observe~='reveal-up'].observed {
      animation: none;
    }
  }

  /* -- Theme toggle -------------------------------------------------------- */
  .erp-root .theme-toggle {
    display: flex;
    gap: var(--space-1);
    background: var(--surface-container);
    border: 1px solid var(--border);
    padding: 2px;
