  /* -- Nav link text -------------------------------------------------------- */
  .erp-root .nav-link-text {
    color: var(--foreground);
  }
  .erp-root .nav-link-text:hover {
    color: var(--primary);
  }

  /* -- Desktop primary nav (top bar) — primary + 2px bar like sticky strip; label centered in 48px via markup items-center -- */
  .erp-root .nav-primary-link {
    box-sizing: border-box;
    color: var(--nav-link);
    font-weight: 500;
    border-bottom-color: transparent;
    margin-bottom: -1px; /* sit on nav 1px border like in-page strips */
    transition:
      color var(--duration-fast) var(--ease-standard),
      border-bottom-color var(--duration-fast) var(--ease-standard);
  }
  .erp-root .nav-primary-link:hover:not(.nav-primary-link--current) {
    color: var(--primary);
    border-bottom-color: var(--primary);
  }
  .erp-root .nav-primary-link--current,.erp-root 
  .nav-primary-link--current:hover {
    color: var(--primary);
    border-bottom-color: var(--primary);
  }
  .erp-root .nav-primary-link:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  /* -- Mobile menu --------------------------------------------------------- */
  .erp-root #mobile-menu {
    position: fixed;
    inset: 0;
    z-index: 100;
    padding: 1rem;
    background: var(--background);
    display: flex;
    align-items: stretch;
    justify-content: flex-start;
    opacity: 0;
    pointer-events: none;
    visibility: hidden;
    transition:
      opacity var(--duration-normal) var(--ease-standard),
      transform var(--duration-normal) var(--ease-standard),
      visibility 0s linear var(--duration-normal);
    transform: translateY(-10px);
    /* Belt-and-braces against overscroll bleed into the body. Body scroll
       is also locked in JS while the menu is open (mobile-menu.js
       lockBodyScroll), but this prevents iOS rubber-band + Android pull-
       to-refresh from triggering on the overlay itself. */
    overscroll-behavior: contain;
  }
  .erp-root #mobile-menu[data-open='true'] {
    opacity: 1;
    pointer-events: auto;
    transform: translateY(0);
    visibility: visible;
    transition:
      opacity var(--duration-normal) var(--ease-standard),
      transform var(--duration-normal) var(--ease-standard),
      visibility 0s linear 0s;
  }
  .erp-root .mobile-menu-shell {
    --mobile-menu-scroll-thumb-size: 2rem;
    --mobile-menu-scroll-thumb-offset: 0px;
    --mobile-menu-scroll-track: color-mix(in oklab, var(--beige-500), transparent 78%);
    --mobile-menu-scroll-thumb: var(--beige-600);
    width: 100%;
    /* Cap to viewport minus the wrapper's 2rem padding so the shell never
       exceeds the visible area. Internal scroll lives on .mobile-menu-main
       below, not here — that way the footer (Sign In CTA) stays pinned at
       the bottom of the shell while brand + items scroll independently. */
    min-height: calc(100dvh - 2rem);
    max-height: calc(100dvh - 2rem);
    overflow: hidden;
    margin-left: 0;
    padding: 1.15rem 0 1rem;
    position: relative;
    border: 1px solid var(--border);
    background:
      linear-gradient(
        180deg,
        color-mix(in oklab, var(--background), var(--primary) 13%) 0%,
        var(--background) 18%
      ),
      var(--background);
    box-shadow: 10px 10px 0 color-mix(in oklab, var(--border), transparent 22%);
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    gap: 0.875rem;
  }
  .erp-root #mobile-menu[data-scrollable='true'] .mobile-menu-shell::after,.erp-root 
  #mobile-menu[data-scrollable='true'] .mobile-menu-shell::before {
    content: '';
    position: absolute;
    right: 1px;
    top: calc(1.15rem + 1px);
    z-index: 2;
    width: 3px;
    pointer-events: none;
  }
  .erp-root #mobile-menu[data-scrollable='true'] .mobile-menu-shell::after {
    bottom: calc(5.75rem + 1px);
    background: var(--mobile-menu-scroll-track);
  }
  .erp-root #mobile-menu[data-scrollable='true'] .mobile-menu-shell::before {
    height: var(--mobile-menu-scroll-thumb-size);
    background: var(--mobile-menu-scroll-thumb);
    transform: translateY(var(--mobile-menu-scroll-thumb-offset));
  }
  .erp-root.dark .mobile-menu-shell {
    --mobile-menu-scroll-track: color-mix(in oklab, var(--beige-300), transparent 76%);
    --mobile-menu-scroll-thumb: var(--beige-400);
  }
  .erp-root .mobile-menu-main {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    flex: 1 1 auto;
    min-height: 0;
    /* This is the actual scroll container. The shell's flex layout pins
       the footer at the bottom (flex: 0 0 auto), so the shell's own
       overflow doesn't engage when content inside main overflows. Make
       main scroll its own children (brand + links) so:
         - footer stays pinned at the shell's bottom edge
         - brand + items scroll independently
         - users always see the Sign In CTA regardless of scroll position
       Same scrollbar styling as the shell so the affordance is consistent. */
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklab, var(--border), transparent 30%) transparent;
  }
  .erp-root .mobile-menu-main::-webkit-scrollbar {
    width: 6px;
  }
  .erp-root .mobile-menu-main::-webkit-scrollbar-track {
    background: transparent;
  }
  .erp-root .mobile-menu-main::-webkit-scrollbar-thumb {
    background: color-mix(in oklab, var(--border), transparent 30%);
    border-radius: 0;
  }
  .erp-root .mobile-menu-dismiss {
    position: absolute;
    top: 1rem;
    right: 0.75rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.25rem;
    height: 2.25rem;
    border: 1px solid color-mix(in oklab, var(--border) 92%, transparent);
    background: color-mix(in oklab, var(--background) 82%, var(--beige-50) 18%);
    color: var(--foreground);
  }
  .erp-root .mobile-menu-brand {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0.45rem;
    padding: 2rem 1rem 0;
    color: var(--foreground);
    text-decoration: none;
  }
  .erp-root .mobile-menu-kicker {
    font-family: var(--font-body);
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--nav-link);
  }
  .erp-root .mobile-menu-cta {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 3rem;
    width: 100%;
    border: 1px solid var(--primary);
    background: var(--primary);
    color: var(--primary-foreground);
    box-shadow: 6px 6px 0 color-mix(in oklab, var(--border), transparent 15%);
    font-family: var(--font-body);
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    text-decoration: none;
  }
  .erp-root .mobile-menu-links {
    display: grid;
    gap: 0.125rem;
    /* Stack from top so overflowing content scrolls cleanly. Prior
       `margin-top: auto` pushed the group to the bottom of .mobile-menu-main
       for the desktop-aesthetic of "brand above, items above the footer",
       but on short viewports the auto-margin collapses and items get
       visually crushed against the footer instead of scrolling. */
    margin-top: 0;
  }
  .erp-root .mobile-menu-link {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    /* Hit-area scaled ~1.9× from the prior 0.6/0.65rem to give a ~75–80px
       tap target at the default font-size. The shell is full-bleed on the
       inline axis, so the feedback band naturally reaches the shell border
       without negative margins inside the scroll container. */
    margin-inline: 0;
    padding: 1.15rem 1rem 1.2rem;
    border-top: 1px solid color-mix(in oklab, var(--border), transparent 8%);
    font-family: var(--font-heading);
    font-size: clamp(1.2rem, 3vw, 1.5rem);
    font-weight: 700;
    line-height: 1;
    text-transform: uppercase;
    letter-spacing: -0.03em;
    text-decoration: none;
    color: var(--foreground);
    /* Button-as-link reset (for .mobile-menu-link--has-children) — keeps
       full-row layout identical to anchor variants. */
    width: 100%;
    background: transparent;
    border-left: 0;
    border-right: 0;
    border-bottom: 0;
    text-align: left;
    cursor: pointer;
    /* Tap feedback: kill the iOS overlay, let :active drive the visible
       state change. visible-system-state heuristic — Nielsen #1. */
    -webkit-tap-highlight-color: transparent;
    touch-action: manipulation;
    transition: background var(--duration-fast) var(--ease-standard);
  }
  .erp-root .mobile-menu-link:active,.erp-root 
  .mobile-menu-link:focus-visible,.erp-root 
  .mobile-menu-link.is-tapped {
    /* JS-driven `.is-tapped` mirrors :active for browsers (Safari iOS) where
       :active terminates on touchend before the flash can register. Class
       lingers ~180ms after pointerup so the band is visible. */
    background: color-mix(in oklab, var(--background), var(--primary) 7%);
  }
  .erp-root .mobile-menu-link:focus-visible {
    outline: var(--outline-width) solid var(--ring);
    outline-offset: calc(var(--outline-offset) * -1);
  }
  .erp-root .mobile-menu-link--current,.erp-root 
  .mobile-menu-link--current .mobile-menu-link-index {
    color: var(--primary);
  }
  .erp-root .mobile-menu-link-index {
    min-width: 1.5rem;
    font-family: var(--font-body);
    font-size: 0.625rem;
    font-weight: 500;
    letter-spacing: 0.18em;
    color: var(--primary);
  }
  .erp-root .mobile-menu-footer {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-top: 0.5rem;
    padding: 0.75rem 1rem 0;
    border-top: 1px solid color-mix(in oklab, var(--border), transparent 8%);
  }
  @media (max-height: 760px) {
    .erp-root #mobile-menu {
      padding: 0.75rem;
    }
    .erp-root .mobile-menu-shell {
      min-height: calc(100dvh - 1.5rem);
      padding: 0.9rem 0 0.875rem;
      gap: 0.75rem;
    }
    .erp-root #mobile-menu[data-scrollable='true'] .mobile-menu-shell::after,.erp-root 
    #mobile-menu[data-scrollable='true'] .mobile-menu-shell::before {
      top: calc(0.9rem + 1px);
      right: 1px;
    }
    .erp-root #mobile-menu[data-scrollable='true'] .mobile-menu-shell::after {
      bottom: calc(5.25rem + 1px);
    }
    .erp-root .mobile-menu-dismiss {
      top: 0.75rem;
      right: 0.625rem;
      width: 2rem;
      height: 2rem;
    }
    .erp-root .mobile-menu-main {
      gap: 0.625rem;
    }
    .erp-root .mobile-menu-brand {
      padding: 1.5rem 0.875rem 0;
    }
    .erp-root .mobile-menu-kicker {
      font-size: 0.625rem;
    }
    .erp-root .mobile-menu-cta {
      min-height: 2.75rem;
      font-size: 0.6875rem;
    }
    .erp-root .mobile-menu-links {
      gap: 0;
    }
    .erp-root .mobile-menu-link {
      margin-inline: 0;
      padding: 0.85rem 0.875rem 0.9rem;
      font-size: 1.05rem;
    }
    .erp-root .mobile-menu-link-index {
      font-size: 0.5625rem;
    }
    .erp-root .mobile-menu-footer {
      margin-top: 0.375rem;
      padding: 0.625rem 0.875rem 0;
    }
  }

  /* -- Catalog patterns (CSS-only tile backgrounds) ----------------------- */
  .erp-root .pat-dots {
    background-image: radial-gradient(circle, currentColor 1px, transparent 1px);
    background-size: 12px 12px;
  }
  .erp-root .pat-lines {
    background-image: repeating-linear-gradient(
      45deg,
      currentColor 0,
      currentColor 1px,
      transparent 1px,
      transparent 8px
    );
  }
  .erp-root .pat-mesh {
    background-image:
      linear-gradient(to right, currentColor 1px, transparent 1px),
      linear-gradient(to bottom, currentColor 1px, transparent 1px);
    background-size: 20px 20px;
  }
  .erp-root .pat-diag {
    background-image: repeating-linear-gradient(
      -45deg,
      currentColor 0,
      currentColor 1px,
      transparent 1px,
      transparent 6px
    );
  }

  /* -- Catalog scroll track ----------------------------------------------- */
  .erp-root .catalog-scroll-track::-webkit-scrollbar {
    display: none;
  }

  /* -- Catalog card hover ------------------------------------------------- */
  .erp-root .catalog-card {
    --catalog-category-accent: var(--catalog-taxonomy-accent, var(--cat-default));

    background: var(--card-bg);
    color: var(--card-fg);
    isolation: isolate;
    outline: 0;
    transition:
      filter 360ms var(--ease-standard),
      box-shadow 420ms var(--ease-standard),
      transform 320ms cubic-bezier(0.16, 1, 0.3, 1);
  }
  .erp-root a.catalog-card,.erp-root 
  .catalog-card--link {
    text-decoration: none;
  }
  .erp-root.dark .catalog-card {
    background: var(--card-bg-d, var(--card-bg));
    color: var(--card-fg-d, var(--card-fg));
  }
  .erp-root .catalog-card:hover {
    filter: brightness(1.12);
    transform: translateY(-3px) scale(1.018);
    z-index: 5;
    box-shadow:
      inset 0 0 0 2px color-mix(in oklab, var(--beige-50), transparent 75%),
      0 0 24px color-mix(in oklab, var(--ink-deep), transparent 30%);
  }
  .erp-root .catalog-card:has(> .catalog-card__hit-target:focus-visible) {
    z-index: 6;
    box-shadow:
      inset 0 0 0 2px var(--ring),
      0 0 0 3px color-mix(in oklab, var(--background), transparent 25%);
  }
  .erp-root .catalog-card:active {
    transform: translateY(0) scale(1.006);
    filter: brightness(1.04);
  }

  .erp-root .catalog-card .pat-dots,.erp-root 
  .catalog-card .pat-lines,.erp-root 
  .catalog-card .pat-mesh,.erp-root 
  .catalog-card .pat-diag {
    opacity: 0.1;
  }

  .erp-root .catalog-card-pattern--subtle {
    opacity: 0.05 !important;
  }

  .erp-root .catalog-card--has-media {
    color: var(--cream);
  }

  .erp-root .catalog-card--has-media::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background:
      linear-gradient(180deg, rgb(0 0 0 / 5%) 0%, rgb(0 0 0 / 16%) 42%, rgb(0 0 0 / 82%) 100%),
      linear-gradient(90deg, rgb(0 0 0 / 24%) 0%, rgb(0 0 0 / 0%) 54%),
      repeating-linear-gradient(
        0deg,
        rgb(255 255 255 / 5%) 0,
        rgb(255 255 255 / 5%) 1px,
        transparent 1px,
        transparent 9px
      );
  }

  .erp-root .catalog-card--has-thumb {
    color: var(--cream);
  }

  .erp-root .catalog-card-media {
    overflow: hidden;
    border-radius: inherit;
    background-position: center;
    background-repeat: no-repeat;
    background-size: cover;
    z-index: 0;
    transform: scale(1.04);
    filter: saturate(1.08) contrast(1.12) brightness(0.94);
    transition: transform 720ms var(--ease-signature);
  }

  .erp-root .catalog-card__image {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .erp-root .catalog-card-media-scrim {
    border-radius: inherit;
    z-index: 1;
    background: linear-gradient(
      180deg,
      rgb(0 0 0 / 14%) 0%,
      rgb(0 0 0 / 24%) 48%,
      rgb(0 0 0 / 58%) 100%
    );
  }

  .erp-root .catalog-card--has-media .pat-dots,.erp-root 
  .catalog-card--has-media .pat-lines,.erp-root 
  .catalog-card--has-media .pat-mesh,.erp-root 
  .catalog-card--has-media .pat-diag {
    z-index: 2;
    color: var(--primary-foreground);
    mix-blend-mode: overlay;
  }

  .erp-root .catalog-card:hover .catalog-card-media {
    transform: scale(1.1);
  }

  /* -- Catalog track wrapper + inline scroll buttons ---------------------- */
  .erp-root .catalog-track-wrap {
    --catalog-rail-pad-x: clamp(0.5rem, 1.6vw, 2rem);
    --catalog-rail-pad-top: clamp(1rem, 1.25vw, 1.35rem);
    --catalog-rail-pad-bottom: 6rem;

    position: relative;
    margin-top: 0;
    margin-bottom: -3rem;
  }

  .erp-root .catalog-inline-scroll {
    display: none; /* shown via JS */
    position: absolute;
    top: 0;
    bottom: 0;
    width: clamp(5.5rem, 10vw, 8.5rem);
    z-index: 90;
    align-items: center;
    justify-content: center;
    border: none;
    cursor: pointer;
    color: white;
    opacity: 1;
    pointer-events: auto;
    text-shadow: 0 2px 18px rgb(0 0 0 / 75%);
    transition:
      opacity 0.18s var(--ease-standard),
      transform 0.24s var(--ease-standard);
  }

  .erp-root .catalog-inline-scroll[data-dir='left'] {
    left: 0;
    background: linear-gradient(
      90deg,
      rgb(0 0 0 / 96%) 0%,
      rgb(0 0 0 / 72%) 52%,
      rgb(0 0 0 / 0) 100%
    );
    transform: translateX(0);
  }

  .erp-root .catalog-inline-scroll[data-dir='right'] {
    right: 0;
    background: linear-gradient(
      270deg,
      rgb(0 0 0 / 96%) 0%,
      rgb(0 0 0 / 72%) 52%,
      rgb(0 0 0 / 0) 100%
    );
    transform: translateX(0);
  }

  .erp-root .catalog-track-wrap:hover .catalog-inline-scroll,.erp-root 
  .catalog-track-wrap:focus-within .catalog-inline-scroll {
    opacity: 0.96;
  }

  .erp-root .catalog-inline-scroll:hover {
    opacity: 1;
  }

  .erp-root .catalog-inline-scroll svg {
    filter: drop-shadow(0 1px 2px rgb(0 0 0 / 95%)) drop-shadow(0 4px 16px rgb(0 0 0 / 95%));
    stroke-width: 2.1;
    transition: transform 0.16s var(--ease-standard);
  }

  .erp-root .catalog-inline-scroll:hover svg,.erp-root 
  .catalog-inline-scroll:focus-visible svg {
    transform: scale(1.08);
  }

  .erp-root .catalog-row-progress[hidden] {
    display: none;
  }

  .erp-root .catalog-row-progress {
    --catalog-scroll-thumb-left: 0%;
    --catalog-scroll-thumb-width: 18%;
    position: absolute;
    right: clamp(1.5rem, 5vw, 4rem);
    bottom: 0.9rem;
    z-index: 11;
    width: clamp(7rem, 18vw, 15rem);
    height: 0.2rem;
    opacity: 0.62;
    pointer-events: none;
    transition: opacity 0.18s var(--ease-standard);
  }

  .erp-root .catalog-row-progress-track {
    position: absolute;
    inset: 0;
    overflow: hidden;
    background: rgb(255 255 255 / 24%);
  }

  .erp-root .catalog-row-progress-thumb {
    position: absolute;
    top: 0;
    bottom: 0;
    left: var(--catalog-scroll-thumb-left);
    width: var(--catalog-scroll-thumb-width);
    background: var(--red);
    transform: translateZ(0);
    transition: background 0.18s var(--ease-standard);
  }

  .erp-root .catalog-track-wrap:hover .catalog-row-progress,.erp-root 
  .catalog-track-wrap:focus-within .catalog-row-progress {
    opacity: 1;
  }
  /* -- Catalog scroll dots ------------------------------------------------ */
  .erp-root .catalog-dot {
    position: relative;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 0;
    border: none;
    padding: 0;
    cursor: pointer;
    flex-shrink: 0;
    background: transparent;
  }

  .erp-root .catalog-dot::before {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 0.9rem;
    height: 0.2rem;
    border-radius: 999px;
    background: var(--foreground);
    content: '';
    opacity: 0.22;
    transform: translate(-50%, -50%);
    transition:
      width var(--duration-fast) var(--ease-standard),
      opacity var(--duration-fast) var(--ease-standard);
  }

  .erp-root .catalog-dot--active::before {
    width: 1.55rem;
    opacity: 1;
  }

  /* -- Catalog filter bar ------------------------------------------------- */
  .erp-root #catalog-filter-bar {
    --catalog-filter-stuck-inset: clamp(var(--space-3), 3vw, var(--space-8));
    --catalog-filter-stuck-width: min(
      calc(
        var(--tacet-nav-bar-width, var(--tacet-nav-width-scrolled)) -
          var(--catalog-filter-stuck-inset)
      ),
      calc(100vw - (2 * var(--space-3)))
    );
    --catalog-filter-stuck-left: calc((100vw - var(--catalog-filter-stuck-width)) / 2);

    position: sticky;
    top: var(--tacet-nav-bottom, var(--chrome-height));
    width: 100%;
    margin-inline: auto;
    min-height: 3.5rem;
    overflow: visible;
    border-bottom: 1px solid var(--border);
    background: var(--background);
    transition:
      border-color var(--duration-normal) var(--ease-standard),
      background var(--duration-normal) var(--ease-standard);
  }

  .erp-root #catalog-filter-bar[data-stuck='true'] {
    min-height: 3.5rem;
    border-bottom: 0;
    background: transparent !important;
  }

  .erp-root .catalog-filter-shell {
    position: relative;
    display: flex;
    width: 100%;
    min-height: 3.5rem;
    align-items: stretch;
    overflow: hidden;
    background: transparent;
    transition:
      border-radius var(--duration-normal) var(--ease-standard),
      background var(--duration-normal) var(--ease-standard),
      box-shadow var(--duration-normal) var(--ease-standard),
      backdrop-filter var(--duration-normal) var(--ease-standard);
  }

  .erp-root .catalog-filter-shell--transitioning {
    will-change: transform;
  }

  .erp-root #catalog-filter-bar[data-stuck='true'] .catalog-filter-shell {
    position: fixed;
    top: calc(var(--tacet-nav-bottom, var(--chrome-height)) - 0.625rem);
    left: var(--catalog-filter-stuck-left);
    z-index: 57;
    width: var(--catalog-filter-stuck-width);
    max-width: var(--catalog-filter-stuck-width);
    min-height: 3.625rem;
    padding-top: 0.625rem;
    border: 1px solid var(--border);
    border-top: 0;
    border-top-left-radius: 0;
    border-top-right-radius: 0;
    border-bottom-right-radius: 0.375rem;
    border-bottom-left-radius: 0.375rem;
    background: color-mix(in oklab, var(--background) 88%, transparent) !important;
    box-shadow: var(--tacet-shadow-sm);
    backdrop-filter: blur(14px) saturate(1.12);
  }

  .erp-root .catalog-filter-track::-webkit-scrollbar {
    display: none;
  }

  .erp-root .catalog-filter-track {
    min-width: 0;
    overflow-y: hidden;
    scrollbar-width: none;
    justify-content: flex-start;
  }

  .erp-root .catalog-filter-scroll {
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    z-index: 2;
    align-items: center;
    justify-content: center;
    width: 2.5rem;
    border: 0;
    border-inline-end: 1px solid var(--border);
    background: linear-gradient(
      to right,
      var(--background) 0%,
      var(--background) 68%,
      transparent 100%
    );
    color: var(--org-on-light);
  }

  .erp-root .catalog-filter-scroll[data-dir='right'] {
    right: 0;
    left: auto;
    border-inline: 1px solid var(--border) 0;
    background: linear-gradient(
      to left,
      var(--background) 0%,
      var(--background) 68%,
      transparent 100%
    );
  }

  .erp-root .catalog-filter-scroll__icon {
    width: 0.875rem;
    height: 0.875rem;
  }

  .erp-root .catalog-filter-scroll:hover {
    color: var(--foreground);
  }

  .erp-root #catalog-filter-bar[data-stuck='true'] .catalog-filter-scroll {
    padding-top: 0.625rem;
    background: color-mix(in oklab, var(--background) 88%, transparent);
  }

  /* -- Catalog filter button — 3D raised button with per-category color ---
     Per-category swatches live in tokens.css (--cat-*). Add a category by
     adding both a token and a row below; values stay in tokens.css. */
  .erp-root .catalog-filter-btn {
    --btn-color: var(--catalog-taxonomy-accent, var(--cat-default));
    --home-category-accent: var(--btn-color);

    position: relative;
    display: inline-flex;
    min-height: 3.5rem;
    flex-direction: column;
    align-items: flex-start;
    justify-content: center;
    gap: var(--space-1);
    border-inline-end: 1px solid var(--border);
    padding: var(--space-2) var(--space-4);
    background: transparent;
    color: var(--text-m);
    font-size: 0.875rem;
    font-weight: 560;
    line-height: 1;
    text-decoration: none;
    transition:
      background var(--duration-fast) var(--ease-standard),
      color var(--duration-fast) var(--ease-standard);
  }

  .erp-root .catalog-filter-btn__label {
    color: var(--foreground);
  }

  .erp-root .catalog-filter-btn__count {
    color: var(--text-m);
    font-family: var(--font-mono);
    font-size: var(--text-label);
    font-variant-numeric: tabular-nums;
    font-weight: 650;
    line-height: 1;
  }

  .erp-root .catalog-filter-btn:hover {
    background: color-mix(in oklab, var(--btn-color) 12%, transparent) !important;
    color: var(--foreground) !important;
  }

  .erp-root .catalog-filter-btn::after {
    content: '';
    position: absolute;
    right: 0.625rem;
    bottom: 0;
    left: 0.625rem;
    height: 3px;
    border-radius: var(--radius-full) var(--radius-full) 0 0;
    background: var(--org-on-light);
    opacity: 0;
    transform: scaleX(0);
    transform-origin: center;
    transition:
      opacity var(--duration-fast) var(--ease-standard),
      transform var(--duration-fast) var(--ease-standard);
  }

  .erp-root .catalog-filter-btn[aria-current='page'],.erp-root 
  .catalog-filter-btn--current,.erp-root 
  .catalog-filter-btn--scroll-active {
    background: transparent !important;
    color: var(--org-on-light) !important;
    font-weight: 650;
  }

  .erp-root .catalog-filter-btn[aria-current='page'] .catalog-filter-btn__label,.erp-root 
  .catalog-filter-btn--current .catalog-filter-btn__label,.erp-root 
  .catalog-filter-btn--scroll-active .catalog-filter-btn__label {
    color: var(--org-on-light);
  }

  .erp-root .catalog-filter-btn[aria-current='page']::after,.erp-root 
  .catalog-filter-btn--current::after,.erp-root 
  .catalog-filter-btn--scroll-active::after {
    opacity: 1;
    transform: scaleX(1);
  }

  .erp-root #catalog-filter-bar[data-scroll-active]
    .catalog-filter-btn[aria-current='page']:not(.catalog-filter-btn--scroll-active) {
    background: transparent !important;
    color: var(--text-m) !important;
    font-weight: 560;
  }

  .erp-root #catalog-filter-bar[data-scroll-active]
    .catalog-filter-btn[aria-current='page']:not(.catalog-filter-btn--scroll-active)
    .catalog-filter-btn__label {
    color: var(--foreground);
  }

  .erp-root #catalog-filter-bar[data-scroll-active]
    .catalog-filter-btn[aria-current='page']:not(.catalog-filter-btn--scroll-active)::after {
    opacity: 0;
    transform: scaleX(0);
  }

  .erp-root .catalog-filter-btn:active {
    background: color-mix(in oklab, var(--btn-color) 18%, transparent) !important;
  }
  .erp-root .catalog-filter-btn:focus-visible,.erp-root 
  .catalog-filter-scroll:focus-visible,.erp-root 
  .catalog-scroll-btn:focus-visible,.erp-root 
  .catalog-inline-scroll:focus-visible {
    outline: var(--outline-width) solid var(--ring);
    outline-offset: -2px;
  }

  /* Center buttons only after JS has confirmed that every item fits. */
