  /* -- Catalog row headers + card badges ---------------------------------- */
  .erp-root .catalog-row {
    scroll-margin-top: calc(
      var(--chrome-height, 4.5rem) + var(--tacet-page-nav-height, 3.25rem) + 1.25rem
    );
    position: relative;
    content-visibility: auto;
    contain-intrinsic-size: auto 27rem;
  }

  .erp-root .catalog-row--card-hovered {
    z-index: 4;
    content-visibility: visible;
  }

  .erp-root .catalog-row--after-card-hover {
    z-index: 5;
    content-visibility: visible;
  }

  .erp-root .catalog-row-header {
    --row-accent: var(--cat-default);
    --row-line: var(--tacet-panel-border, color-mix(in oklab, var(--border), transparent 12%));
    --row-accent-quiet: color-mix(in oklab, var(--row-accent), transparent 82%);
    position: relative;
    z-index: 1;
    isolation: isolate;
    overflow: visible;
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) auto;
    column-gap: clamp(1.25rem, 3vw, 3rem);
    row-gap: 0.85rem;
    align-items: start;
    min-height: auto;
    border-top: 0;
    background: transparent;
  }

  .erp-root .catalog-row-header::before,.erp-root 
  .catalog-row-header::after {
    content: none;
  }

  .erp-root .catalog-row-copy {
    position: relative;
    z-index: 1;
    display: grid;
    width: 100%;
    max-width: none;
    grid-template-columns: minmax(0, max-content) auto minmax(0, 1fr);
    align-items: center;
    gap: 0.62rem clamp(0.75rem, 1.45vw, 1.15rem);
  }

  .erp-root .catalog-row-heading {
    display: block !important;
    grid-column: 1;
    grid-row: 1;
    min-width: 0;
    line-height: var(--tacet-type-heading-lh, 1.08);
  }

  .erp-root .catalog-row-title,.erp-root 
  .home-catalog-results__heading {
    font-family: var(--font-heading);
    font-size: var(--text-2xl);
    font-weight: var(--font-weight-bold);
  }

  @media (min-width: 48rem) {
    .erp-root .catalog-row-title,.erp-root 
    .home-catalog-results__heading {
      font-size: var(--text-3xl);
    }
  }

  .erp-root .catalog-row-title {
    display: flex;
    max-width: none;
    align-items: center;
    gap: 0.5rem;
    margin: 0;
    color: var(--foreground);
    text-transform: none;
    text-wrap: balance;
    white-space: nowrap;
  }

  .erp-root .catalog-row-title__icon {
    width: 0.95em;
    height: 0.95em;
    flex: none;
    color: var(--row-accent);
    stroke-width: 2;
  }

  .erp-root .catalog-row-title__label {
    overflow: hidden;
    min-width: 0;
    text-overflow: ellipsis;
  }

  .erp-root .catalog-row-count {
    display: inline-grid;
    grid-template-columns: minmax(0, auto) auto;
    align-items: center;
    overflow: hidden;
    width: fit-content;
    max-width: min(100%, 28rem);
    margin: 0;
    padding: 0;
    border: 1px solid transparent;
    border-radius: 999px;
    background: transparent;
    color: var(--foreground);
    font-family: var(--font-body);
    font-size: 0.74rem;
    font-weight: 560;
    grid-column: 2;
    grid-row: 1;
    letter-spacing: 0;
    line-height: 1.1;
    text-align: left;
    text-decoration: none;
    text-transform: none;
    white-space: normal;
    cursor: pointer;
    appearance: none;
    gap: 0;
    transform: translateY(0.04em);
    transition:
      border-color 160ms var(--ease-standard),
      color 0.16s var(--ease-standard),
      transform 0.16s var(--ease-standard);
  }

  .erp-root .catalog-row-count:hover {
    color: var(--foreground);
    transform: translateY(0.04em);
  }

  .erp-root .catalog-row-count:focus-visible {
    border-radius: 0.5rem;
    outline: 2px solid color-mix(in oklab, var(--row-accent), var(--foreground) 10%);
    outline-offset: 0.45rem;
  }

  .erp-root .catalog-row-count__rail {
    display: none;
  }

  .erp-root .catalog-row-count__copy {
    display: grid;
    min-width: 0;
    gap: 0.25rem;
  }

  .erp-root .catalog-row-count__total {
    display: block;
    min-width: 0;
    color: color-mix(in oklab, var(--foreground), var(--row-accent) 22%);
    font-size: inherit;
    font-weight: 700;
    line-height: 1.1;
  }

  .erp-root .catalog-row-count__separator {
    display: none;
    color: var(--row-accent-quiet);
    font-weight: 850;
    line-height: 1;
  }

  .erp-root .catalog-row-count__coverage {
    display: none;
  }

  .erp-root .catalog-row-count .catalog-row-count__arrow {
    flex-shrink: 0;
    display: inline-grid;
    width: 2.15rem;
    height: auto;
    min-height: 1.75rem;
    align-self: stretch;
    place-items: center;
    border: 0;
    border-inline-start: 1px solid var(--catalog-row-count-divider-color);
    border-radius: 0 calc(var(--catalog-row-count-radius) - 1px)
      calc(var(--catalog-row-count-radius) - 1px) 0;
    background: transparent;
    color: color-mix(in oklab, var(--row-accent), var(--foreground) 12%);
    transition:
      color 180ms var(--ease-standard),
      transform 180ms var(--ease-decelerate);
  }

  .erp-root .catalog-row-tools {
    position: static;
    z-index: 2;
    flex-shrink: 0;
    align-self: start;
    justify-self: end;
    max-inline-size: min(14rem, 32vw);
    overflow: hidden;
    padding-top: clamp(0.78rem, 0.95vw, 0.98rem);
    padding-bottom: 0;
    transform: none;
  }

  .erp-root .catalog-card-badge {
    display: inline-flex;
    align-self: flex-start;
    max-width: calc(100% - 1.5rem);
    align-items: center;
    min-height: 1.35rem;
    padding: 0.24rem 0.45rem;
    border: 1px solid color-mix(in oklab, var(--tacet-saas-accent, var(--red)), transparent 34%);
    border-radius: 2px;
    background: color-mix(in oklab, var(--tacet-saas-accent, var(--red)), black 8%);
    box-shadow: none;
    color: white;
    font-family: var(--font-mono);
    font-size: 0.62rem;
    font-weight: 760;
    letter-spacing: 0.075em;
    line-height: 1;
    pointer-events: none;
    text-transform: uppercase;
    transform: translateZ(0);
    transition: transform var(--duration-fast) var(--ease-standard);
  }

  .erp-root .catalog-card:hover .catalog-card-badge {
    transform: translateY(-1px);
  }

  .erp-root .catalog-card__persistent-badges {
    position: absolute;
    z-index: 7;
    top: 0;
    right: clamp(0.75rem, 1vw, 1rem);
    display: flex;
    pointer-events: none;
    transform: scaleX(var(--catalog-arrow-x-comp)) scaleY(var(--catalog-arrow-y-comp));
    transform-origin: right top;
    transition: transform 320ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  .erp-root .catalog-card-category-pill,.erp-root 
  .catalog-card-recent-tag {
    display: inline-flex;
    min-height: 1.35rem;
    align-items: center;
    overflow: hidden;
    border-radius: var(--radius-xs);
    padding: 0.24rem 0.45rem;
    font-family: var(--font-body);
    font-size: 0.62rem;
    font-weight: 760;
    letter-spacing: 0.04em;
    line-height: 1;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  .erp-root .catalog-card-category-pill,.erp-root 
  .home-category-tag__face {
    --category-tint-border: color-mix(in oklab, var(--category-tint-accent), transparent 78%);
    --category-tint-fill: color-mix(in oklab, var(--category-tint-accent), transparent 94%);

    border: 1px solid var(--category-tint-border);
  }

  .erp-root .catalog-card-category-pill {
    --category-tint-accent: var(--catalog-category-accent);

    min-width: 0;
    border-color: color-mix(in oklab, var(--catalog-category-accent), black 18%);
    background: var(--catalog-category-accent);
    color: var(--cat-on);
    font-family: var(--font-catalog-display);
    font-size: clamp(0.68rem, 2.6cqw, 0.75rem);
  }

  .erp-root .catalog-card__rest-copy .catalog-card-category-pill,.erp-root 
  .catalog-card__overlay-copy .catalog-card-category-pill {
    width: max-content;
    max-width: 100%;
    flex: none;
    align-self: flex-start;
  }

  .erp-root .catalog-card__overlay-copy .catalog-card-category-pill {
    max-width: none;
  }

  .erp-root .catalog-card-recent-tag {
    flex: none;
    border: 1px solid color-mix(in oklab, var(--red), transparent 34%);
    background: color-mix(in oklab, var(--red), black 8%);
    color: white;
  }

  .erp-root .catalog-card-category-pill[hidden],.erp-root 
  .catalog-card-recent-tag[hidden] {
    display: none;
  }

  /* -- Catalog gallery adaptation ---------------------------------------- */
  .erp-root .catalog-scroll-track--gallery {
    display: grid;
    grid-auto-columns: minmax(18.5rem, 84vw);
    grid-auto-flow: column;
    gap: 0.625rem;
    align-items: start;
    overflow-x: auto;
    overflow-y: clip;
    overflow-clip-margin: 100px;
    padding: var(--catalog-rail-pad-top) var(--catalog-rail-pad-x) var(--catalog-rail-pad-bottom);
    background: var(--background);
    scroll-padding-inline: var(--catalog-rail-pad-x);
    scroll-snap-type: x proximity;
    -webkit-overflow-scrolling: touch;
  }

  .erp-root .catalog-scroll-track--gallery::-webkit-scrollbar {
    display: none;
  }

  .erp-root .catalog-scroll-track--gallery[data-catalog-layout='mixed'] {
    grid-template-rows: repeat(2, minmax(0, 1fr));
  }

  .erp-root .catalog-scroll-track--gallery > .catalog-card {
    --catalog-card-radius: 6px;
    --catalog-hover-transform: translateX(0) translateY(0) scaleX(1) scaleY(1);
    --catalog-card-hover-shadow:
      0 1px 2px rgb(18 15 12 / 0.14),
      0 14px 34px -26px color-mix(in oklab, var(--ink-deep), transparent 66%);
    --catalog-image-y-comp: 1;
    --catalog-content-x-comp: 1;
    --catalog-arrow-x-comp: 1;
    --catalog-arrow-y-comp: 1;
    --catalog-parallax-x: 0px;
    --catalog-parallax-y: 0px;
    --catalog-card-hover-enter-duration: 240ms;
    --catalog-card-hover-exit-duration: 140ms;
    --catalog-card-backdrop-duration: 220ms;
    --catalog-card-hover-enter-ease: cubic-bezier(0.22, 1, 0.36, 1);
    --catalog-card-hover-move-ease: cubic-bezier(0.25, 1, 0.5, 1);
    position: relative;
    display: block;
    width: 100%;
    aspect-ratio: 430 / 262;
    padding: 0;
    overflow: hidden;
    border: 0;
    border-radius: var(--catalog-card-radius);
    clip-path: inset(0 round var(--catalog-card-radius));
    background: var(--card-bg);
    color: white;
    container-type: inline-size;
    cursor: pointer;
    isolation: isolate;
    outline: 0;
    scroll-snap-align: start;
    transform: translateZ(0);
    transform-origin: center center;
    transition:
      opacity 260ms var(--ease-decelerate),
      filter 180ms var(--catalog-card-hover-enter-ease),
      box-shadow 200ms var(--catalog-card-hover-enter-ease),
      transform 260ms var(--catalog-card-hover-move-ease);
    user-select: none;
    touch-action: pan-x pan-y;
    -webkit-mask-image: linear-gradient(#fff 0 0);
    -webkit-mask-repeat: no-repeat;
    -webkit-mask-size: 100% 100%;
  }

  .erp-root .catalog-scroll-track--gallery > .catalog-card--hydrating {
    opacity: 0;
    transform: translate3d(0, 0.75rem, 0) scale(0.985);
  }

  .erp-root .catalog-scroll-track--gallery > .catalog-card--hydrating.catalog-card--hydrated {
    opacity: 1;
    transform: translateZ(0) scale(1);
  }

  .erp-root .catalog-scroll-track--gallery > .catalog-card::before {
    position: absolute;
    inset: 0;
    z-index: 8;
    border-radius: inherit;
    box-shadow:
      inset 0 0 0 1px rgb(255 255 255 / 24%),
      inset 0 1px 0 rgb(255 255 255 / 34%),
      inset 0 -1px 0 rgb(0 0 0 / 34%);
    content: '';
    pointer-events: none;
  }

  .erp-root .catalog-scroll-track--gallery > .catalog-card::after {
    z-index: 2;
    background:
      linear-gradient(180deg, rgb(0 0 0 / 2%) 0%, rgb(0 0 0 / 12%) 42%, rgb(0 0 0 / 62%) 100%),
      linear-gradient(90deg, rgb(0 0 0 / 16%) 0%, rgb(0 0 0 / 0%) 58%);
  }

  .erp-root .catalog-scroll-track--gallery > .catalog-card--portrait {
    aspect-ratio: 430 / 501;
  }

  .erp-root .catalog-scroll-track--gallery > .catalog-card--mixed-portrait {
    grid-row: span 2;
  }

  .erp-root .catalog-scroll-track--gallery > .catalog-card--hovered,.erp-root 
  .catalog-scroll-track--gallery > .catalog-card:hover {
    z-index: 100;
    filter: brightness(1.05) saturate(1.03);
    box-shadow:
      var(--catalog-card-hover-shadow),
      inset 0 0 0 1px rgb(255 255 255 / 34%);
    transform: var(--catalog-hover-transform);
    will-change: transform;
  }

  .erp-root .catalog-scroll-track--gallery > .catalog-card:has(> .catalog-card__hit-target:focus-visible) {
    z-index: 101;
    box-shadow:
      0 0 0 3px var(--background),
      0 0 0 5px var(--ring),
      var(--catalog-card-hover-shadow);
  }

  .erp-root .catalog-scroll-track--gallery .catalog-card-media {
    inset: 0;
    z-index: 0;
    border-radius: inherit;
    transform: scale(1.02);
    filter: saturate(1.04) contrast(1.08) brightness(0.94);
    transition:
      filter 220ms var(--catalog-card-hover-enter-ease),
      transform 280ms var(--catalog-card-hover-move-ease);
  }

  .erp-root .catalog-scroll-track--gallery .catalog-card__image {
    width: 100%;
    height: 100%;
    object-fit: cover;
