    background: var(--card) !important;
  }
  .erp-root .pricing-table tr:not([style*='background']):hover td:last-child {
    color: var(--red) !important;
  }

  /* -- Range slider thumb ------------------------------------------------- */
  .erp-root input[type='range']::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 14px;
    height: 14px;
    background: var(--red);
    cursor: pointer;
  }
  .erp-root input[type='range']::-moz-range-thumb {
    width: 14px;
    height: 14px;
    background: var(--red);
    border: none;
    cursor: pointer;
  }

  /* -- Line clamp utility ------------------------------------------------- */
  .erp-root .line-clamp-2 {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  /* -- Catalog search active state ---------------------------------------- */
  .erp-root .catalog-search-active {
    background: var(--surface-container-highest);
  }

  /* -- Catalog search results: keep normal row/scroll behaviour ---------- */
  .erp-root .catalog-search-mode .catalog-row {
    border-bottom: none;
  }

  /* -- Sticky in-page anchor strips (scroll spy; matches enterprise-suite-subnav-01) -- */
  .erp-root [data-inpage-nav] {
    --inpage-nav-active: var(--org-on-light);
    position: relative; /* containing block for the injected arrow buttons */
  }

  .erp-root [data-inpage-nav]:not(.proto-page-nav):not(.tacet-page-nav) {
    background: color-mix(in oklab, var(--background), transparent 4%) !important;
    backdrop-filter: blur(14px) saturate(1.1);
  }

  /* Hide the native horizontal scrollbar — on mobile webkit a visible
     bar eats vertical space below the strip and leaks past the sticky
     header look. inpage-nav-scrollspy.js injects [<] / [>] buttons
     when scrollWidth > clientWidth so the user can still navigate
     off-screen items. */
  .erp-root [data-inpage-nav] > div {
    scrollbar-width: none;
    -ms-overflow-style: none;
  }
  .erp-root [data-inpage-nav] > div::-webkit-scrollbar {
    display: none;
  }

  /* Arrow buttons — injected by inpage-nav-scrollspy.js. Hidden by
     default; JS toggles `display: flex` whenever the strip can scroll
     in that direction. */
  .erp-root .inpage-nav-arrow {
    position: absolute;
    top: 0;
    bottom: 0;
    width: 36px;
    display: none;
    align-items: center;
    justify-content: center;
    background: var(--background);
    color: var(--text-m);
    font-family: var(--font-body);
    font-size: 18px;
    line-height: 1;
    cursor: pointer;
    z-index: 1;
    padding: 0;
  }
  .erp-root .inpage-nav-arrow--left {
    left: 0;
    border-right: 1px solid var(--border);
  }
  .erp-root .inpage-nav-arrow--right {
    right: 0;
    border-left: 1px solid var(--border);
  }
  .erp-root .inpage-nav-arrow:hover,.erp-root 
  .inpage-nav-arrow:focus-visible {
    color: var(--foreground);
  }
  .erp-root .inpage-nav-arrow:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: -2px;
  }

  .erp-root [data-inpage-nav][data-inpage-accent='org'] {
    --inpage-nav-active: var(--org-on-light);
  }

  /* Match enterprise suite strip: --nav-link + transparent 2px bar; active = accent */
  .erp-root [data-inpage-nav] a[href^='#'] {
    color: var(--nav-link);
    font-family: var(--font-body);
    font-size: 0.8125rem;
    font-weight: 500;
    letter-spacing: 0;
    border-bottom-color: transparent;
    text-transform: none;
  }

  .erp-root [data-inpage-nav] a[href^='#'].inpage-nav-link--active {
    color: var(--inpage-nav-active);
    border-bottom-color: var(--inpage-nav-active);
  }

  .erp-root [data-inpage-nav] a[href^='#']:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }

  .erp-root #cta .btn--ghost {
    --btn-rail: var(--cta-accent-text);
    --btn-rail-hover: var(--cta-accent-text);
  }

  .erp-root #cta:not(.proto-cta--left) .btn--ghost {
    --btn-text-hover: var(--cream);

    box-shadow: inset 0 -1px 0 color-mix(in oklab, var(--cream), transparent 72%);
  }

  /* -- SDK tabs (proto/sdk-01) -------------------------------------------- */
  .erp-root .sdk-tab-btn {
    color: var(--text-m);
    border-bottom-color: transparent;
  }
  .erp-root .sdk-tab-btn[aria-selected='true'] {
    color: var(--org-on-light);
    border-bottom-color: var(--org);
  }
  .erp-root .sdk-tab-btn:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }

  /* -- Yellow highlight: text stays dark in both modes ----------------------
     Yellow is theme-constant, so any element rendering text ON --accent-yellow
     must use --accent-yellow-fg for foreground. Centralized here so feature/
     agent/agents-listing pages don't each have to remember it. */
  /* `.accent` spans inside h1/h2 sit on a yellow highlighter swipe, so
     their text must use the paired `--accent-yellow-fg` token to stay
     legible. The `.ft-cta-bottom .btn` / `.ag-cta-bottom .btn` /
     `.agi-cta-bottom .btn` selectors were dropped from this list when
     those bottom CTAs migrated to canonical `.btn .btn--primary`
     (signal-red bg, cream text via `--primary-foreground`) — leaving
     them in here forced black text on red. */
  .erp-root .ft-hero h1 .accent,.erp-root 
  .ft-section h2 .accent,.erp-root 
  .ft-agent-card .agt-saves,.erp-root 
  .ft-cta-bottom .accent,.erp-root 
  .ag-section .ag-h2 .accent,.erp-root 
  .ag-cta-bottom .accent,.erp-root 
  .agi-hero h1 .accent,.erp-root 
  .agi-card .meta .saves,.erp-root 
  .agi-cta-bottom .accent {
    color: var(--accent-yellow-fg);
  }

  /* -- Hero catalog (hero-catalog.njk on /) -------------------------------
     Outlined packet object inspired by the Proto signature artifact. Fixed
     row sizing keeps glitch text from shifting the first viewport. */
  .erp-root .hero-catalog {
    --hero-packet-ink: var(--ink-deep);
    --hero-packet-muted: var(--ink-mid);
    --hero-packet-line: color-mix(in oklab, var(--ink-deep), transparent 78%);
    --hero-packet-cell: color-mix(in oklab, var(--background), var(--beige-100) 34%);
    --hero-packet-soft: color-mix(in oklab, var(--beige-200), var(--background) 58%);
    --hero-packet-cta: var(--hero-packet-accent);
    --hero-packet-cta-text: var(--beige-50);
    --hero-packet-accent: var(--org-on-light);
    --hero-cta-rule-color: var(--org-on-light);

    overflow: hidden;
    background: transparent;
    block-size: clamp(37rem, 48vw, 42rem);
    min-block-size: 37rem;
    max-block-size: 42rem;
  }

  .erp-root.dark .hero-catalog {
    --hero-packet-ink: var(--beige-100);
    --hero-packet-muted: color-mix(in oklab, var(--beige-300), transparent 18%);
    --hero-packet-line: color-mix(in oklab, var(--beige-200), transparent 82%);
    --hero-packet-cell: color-mix(in oklab, var(--beige-900), var(--beige-950) 34%);
    --hero-packet-soft: color-mix(in oklab, var(--beige-800), var(--beige-950) 42%);
    --hero-packet-cta: var(--hero-packet-accent);
    --hero-packet-cta-text: var(--beige-50);
    --hero-packet-accent: var(--org);
    --hero-cta-rule-color: var(--org);
  }

  .erp-root .hero-catalog__inner {
    display: flex;
    width: var(--tacet-nav-width, min(calc(100% - clamp(4rem, 18vw, 18rem)), 58rem));
    height: 100%;
    align-items: center;
    margin-inline: auto;
    padding-block: clamp(2.5rem, 3.5vw, 4.5rem) clamp(1.5rem, 2.5vw, 3.5rem);
  }

  .erp-root .hero-catalog__packet {
    --hero-packet-inset: clamp(1.35rem, 2.1vw, 1.75rem);
    --hero-metal-surface-a: color-mix(in oklab, var(--beige-100), white 8%);
    --hero-metal-surface-b: color-mix(in oklab, var(--beige-200), var(--beige-50) 18%);
    --hero-metal-surface-c: color-mix(in oklab, var(--beige-300), var(--beige-100) 18%);
    --hero-metal-surface-d: color-mix(in oklab, var(--beige-400), var(--beige-200) 24%);
    --hero-metal-surface-e: color-mix(in oklab, var(--beige-500), var(--beige-300) 30%);
    --hero-metal-flare-a: color-mix(in oklab, var(--beige-100), white 8%);
    --hero-metal-flare-b: color-mix(in oklab, var(--beige-400), var(--pur) 8%);
    --hero-metal-flare-c: color-mix(in oklab, var(--beige-500), var(--hero-packet-accent) 9%);
    --hero-metal-sheen: radial-gradient(64% 87% at 12.2% 21.5%, #fefaf5 0%, #ded8d3 100%);

    position: relative;
    display: grid;
    grid-template-rows:
      minmax(2.25rem, auto)
      minmax(8.75rem, 1fr)
      minmax(3.65rem, auto)
      minmax(2.75rem, auto)
      minmax(2.75rem, auto);
    width: 100%;
    height: min(34rem, calc(100% - clamp(3.5rem, 6vw, 7rem)));
    min-height: 24rem;
    max-height: none;
    overflow: hidden;
    border: 1px solid var(--hero-packet-line);
    border-radius: var(--radius-lg);
    background: color-mix(in oklab, var(--hero-packet-cell), transparent 8%);
    box-shadow: var(--shadow-sm);
    transition: box-shadow var(--duration-normal) var(--ease-standard);
  }

  .erp-root.dark .hero-catalog__packet {
    --hero-metal-surface-a: color-mix(in oklab, var(--beige-700), var(--beige-800) 38%);
    --hero-metal-surface-b: color-mix(in oklab, var(--beige-800), var(--beige-700) 18%);
    --hero-metal-surface-c: color-mix(in oklab, var(--beige-900), var(--beige-800) 32%);
    --hero-metal-surface-d: color-mix(in oklab, var(--beige-800), var(--beige-950) 22%);
    --hero-metal-surface-e: color-mix(in oklab, var(--beige-700), var(--beige-900) 42%);
    --hero-metal-flare-a: color-mix(in oklab, var(--beige-500), transparent 66%);
    --hero-metal-flare-b: color-mix(in oklab, var(--pur), transparent 84%);
    --hero-metal-flare-c: color-mix(in oklab, var(--hero-packet-accent), transparent 82%);
    --hero-metal-sheen: radial-gradient(
      64% 87% at 12.2% 21.5%,
      color-mix(in oklab, var(--beige-500), transparent 58%) 0%,
      color-mix(in oklab, var(--beige-900), transparent 26%) 100%
    );
  }

  .erp-root .hero-catalog__packet::before,.erp-root 
  .hero-catalog__packet::after {
    content: '';
    position: absolute;
    inset-block: 0;
    z-index: 0;
    width: 50%;
    opacity: 0;
    pointer-events: none;
    background:
      radial-gradient(
        circle at var(--hero-glare-x, 50%) var(--hero-glare-y, 50%),
        color-mix(in oklab, var(--hero-metal-surface-a), white 14%) 0%,
        color-mix(in oklab, var(--hero-metal-surface-a), transparent 58%) 16%,
        transparent 38%
      ),
      var(--hero-metal-sheen),
      radial-gradient(circle at 12% 18%, var(--hero-metal-flare-a) 0%, transparent 34%),
      radial-gradient(circle at 88% 12%, var(--hero-metal-flare-b) 0%, transparent 34%),
      radial-gradient(circle at 80% 92%, var(--hero-metal-flare-c) 0%, transparent 42%),
      linear-gradient(
        118deg,
        var(--hero-metal-surface-a) 0%,
        var(--hero-metal-surface-b) 22%,
        var(--hero-metal-surface-c) 42%,
        var(--hero-metal-surface-d) 62%,
        var(--hero-metal-surface-e) 82%,
        var(--hero-metal-surface-d) 100%
      );
    transition: opacity var(--duration-normal) var(--ease-standard);
  }

  .erp-root .hero-catalog__packet::before {
    inset-inline-start: 0;
  }

  .erp-root .hero-catalog__packet::after {
    inset-inline-end: 0;
  }

  .erp-root .hero-catalog__packet[data-hero-hover-side='human']::before,.erp-root 
  .hero-catalog__packet:has(.hero-catalog__story--human:hover)::before,.erp-root 
  .hero-catalog__packet:has(.hero-catalog__story--human:focus-within)::before {
    opacity: 0.96;
  }

  .erp-root .hero-catalog__packet[data-hero-hover-side='agent']::after,.erp-root 
  .hero-catalog__packet:has(.hero-catalog__story--agent:hover)::after,.erp-root 
  .hero-catalog__packet:has(.hero-catalog__story--agent:focus-within)::after {
    opacity: 0.96;
  }

  .erp-root .hero-catalog__row {
    position: relative;
    z-index: 2;
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    border-bottom: 1px solid var(--hero-packet-line);
  }

  .erp-root .hero-catalog__row > * + * {
    border-left: 1px solid var(--hero-packet-line);
  }

  .erp-root .hero-catalog__row--top {
    min-height: 2.25rem;
  }

  .erp-root .hero-catalog__layer-icon {
    width: 0.85rem;
    height: 0.85rem;
    flex: none;
    stroke-width: 2.5;
  }

  .erp-root .hero-catalog__layer-icon--agent {
    --hero-catalog-icon-direction: -1;

    color: var(--hero-packet-accent);
    transform: scaleX(-1);
  }

  .erp-root .hero-catalog__row--story {
    align-items: stretch;
  }

  .erp-root .hero-catalog__story {
    position: relative;
    isolation: isolate;
    display: grid;
    grid-template-rows: auto minmax(4.1rem, 1fr) minmax(2.1rem, auto);
    align-content: center;
    gap: clamp(0.4rem, 0.6vw, 0.8rem);
    min-width: 0;
    padding: clamp(0.75rem, 1vw, 1.25rem) var(--hero-packet-inset);
    overflow: hidden;
    transition:
      color var(--duration-fast) var(--ease-standard),
      box-shadow var(--duration-fast) var(--ease-standard);
  }

  .erp-root .hero-catalog__story > * {
    position: relative;
    z-index: 1;
  }

  .erp-root .hero-catalog__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: var(--hero-catalog-eyebrow-gap);
    color: var(--hero-packet-muted);
    font-family: var(--font-body);
    font-size: var(--hero-catalog-copy-size);
    font-weight: 650;
    letter-spacing: 0;
    line-height: 1.2;
  }

  .erp-root .hero-catalog__eyebrow .hero-catalog__layer-icon {
    transform-box: fill-box;
    transform-origin: center;
    transition: transform var(--duration-fast) var(--ease-decelerate);
  }

  @keyframes hero-catalog-icon-signal {
    0%,
    100% {
      transform: scaleX(var(--hero-catalog-icon-direction, 1)) translateY(0) rotate(0) scale(1);
    }
    12% {
      transform: scaleX(var(--hero-catalog-icon-direction, 1)) translateY(-0.15rem) rotate(-14deg)
        scale(1.18);
    }
    26% {
      transform: scaleX(var(--hero-catalog-icon-direction, 1)) translateY(0.04rem) rotate(12deg)
        scale(1.08);
    }
    42% {
      transform: scaleX(var(--hero-catalog-icon-direction, 1)) translateY(-0.1rem) rotate(-10deg)
        scale(1.16);
    }
    58% {
      transform: scaleX(var(--hero-catalog-icon-direction, 1)) translateY(0) rotate(7deg)
        scale(1.09);
    }
    74% {
      transform: scaleX(var(--hero-catalog-icon-direction, 1)) translateY(-0.05rem) rotate(-4deg)
        scale(1.13);
    }
    88% {
      transform: scaleX(var(--hero-catalog-icon-direction, 1)) translateY(0) rotate(2deg)
        scale(1.07);
    }
  }

  .erp-root .hero-catalog__story--human .hero-catalog__eyebrow {
    justify-self: end;
    margin-inline-end: var(--space-4);
    text-align: right;
  }

  .erp-root .hero-catalog__story--agent .hero-catalog__eyebrow {
    justify-self: start;
    margin-inline-start: var(--space-4);
    text-align: left;
  }

  .erp-root .hero-catalog__metric > *,.erp-root 
  .hero-catalog__steps > * {
    position: relative;
    z-index: 1;
  }

  .erp-root .hero-catalog__packet[data-hero-hover-side='human']
    .hero-catalog__panel--human
    .hero-catalog__metric,.erp-root 
  .hero-catalog__packet[data-hero-hover-side='agent']
    .hero-catalog__panel--agent
    .hero-catalog__metric {
    background: transparent;
  }

  .erp-root .hero-catalog__headline {
    --hero-headline-fit: 1;
    --hero-headline-lines: 1;
    --hero-headline-size: clamp(2.75rem, 4.4vw, 3.9rem);

    display: block;
    max-width: min(100%, 14ch);
    min-height: 2.08em;
    margin: 0;
    color: var(--hero-packet-ink);
    font-family: var(--font-display);
    font-size: calc(var(--hero-headline-size) * var(--hero-headline-fit));
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1.06;
    text-wrap: balance;
  }

  .erp-root .hero-catalog__headline > span {
    display: block;
    min-height: 2.04em;
    line-height: inherit;
  }

  .erp-root .hero-catalog__headline .hero-headline__line {
    display: block;
    line-height: 1.06;
    white-space: nowrap;
  }

  .erp-root .hero-catalog__story--agent .hero-catalog__headline {
    color: var(--hero-packet-accent);
  }

  .erp-root .hero-catalog__description {
    max-width: 36ch;
    min-height: 2.7em;
    margin: 0;
    color: var(--hero-packet-muted);
    font-size: clamp(0.8rem, 0.95vw, 0.95rem);
    font-weight: 560;
    line-height: 1.5;
    transition:
      opacity 160ms ease,
      transform 160ms ease;
    text-wrap: pretty;
  }

  .erp-root .hero-catalog__description.is-glitching {
    opacity: 0.4;
    transform: translateY(0.125rem);
  }

  .erp-root .hero-catalog__row--metrics {
    background: transparent;
  }

  .erp-root .hero-catalog__metric {
    position: relative;
    isolation: isolate;
    display: flex;
    align-items: center;
    min-height: 3.65rem;
    padding: 0.72rem var(--hero-packet-inset);
    overflow: hidden;
    background: transparent;
    color: var(--hero-packet-muted);
    font-size: 0.78rem;
    line-height: 1.3;
  }

  .erp-root .hero-catalog__metric-box {
    display: grid;
    gap: 0.2rem;
    width: 100%;
    max-width: 25rem;
    padding: var(--space-4) var(--space-8);
    border: 1px solid var(--hero-packet-line);
    background: color-mix(in oklab, var(--hero-packet-soft), transparent 18%);
  }

  .erp-root .hero-catalog__metric-box p {
    margin: 0;
  }

  .erp-root .hero-catalog__metric-box strong {
    color: var(--hero-packet-accent);
    font-weight: 720;
  }

  .erp-root .hero-catalog__row--cta {
    background: transparent;
  }

  .erp-root .hero-catalog__cta {
    position: relative;
    isolation: isolate;
    display: flex;
    min-height: 2.75rem;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: 0.58rem var(--hero-packet-inset);
    overflow: hidden;
    background: var(--hero-packet-cell);
    color: var(--hero-packet-ink);
    font-family: var(--font-body);
    font-size: clamp(0.95rem, 1.1vw, 1.05rem);
    font-weight: 680;
    line-height: 1;
    text-decoration: none;
    transition:
      background var(--duration-fast) var(--ease-standard),
      color var(--duration-fast) var(--ease-standard),
      box-shadow var(--duration-fast) var(--ease-standard);
  }

  /* Copy-prompt variant — the agent-panel CTA is a <button>; normalize UA
     chrome so it renders identically to the anchor variant. */
  .erp-root button.hero-catalog__cta {
    inline-size: 100%;
    cursor: pointer;
    text-align: start;
    appearance: none;
  }

  .erp-root .hero-catalog__cta-group {
    display: inline-flex;
    gap: 0.75rem;
    align-items: center;
  }

  .erp-root .hero-catalog__cta::before {
    position: absolute;
    inset: 0;
    background:
      linear-gradient(90deg, var(--hero-cta-rule-color), var(--hero-cta-rule-color)),
      linear-gradient(
        90deg,
        var(--hero-cta-metal-a) 0%,
        var(--hero-cta-metal-b) 34%,
        var(--hero-cta-metal-c) 58%,
        var(--hero-cta-metal-b) 82%,
        var(--hero-cta-metal-a) 100%
      );
    background-position:
      0 100%,
      0 0;
    background-repeat: no-repeat;
    background-size:
      100% var(--hero-cta-rule-resting),
      0 100%;
    content: '';
    opacity: 0.98;
    transition: background-size var(--duration-normal) var(--ease-decelerate);
    pointer-events: none;
  }

  .erp-root .hero-catalog__cta > * {
    position: relative;
    z-index: 1;
  }

  .erp-root .hero-catalog__cta svg {
    flex: none;
    transition: transform var(--duration-fast) var(--ease-standard);
  }

  .erp-root .hero-catalog__cta:hover,.erp-root 
  .hero-catalog__cta:focus-visible {
    color: var(--hero-packet-cta-text);
    box-shadow: inset 0 0 0 1px var(--hero-packet-accent);
  }

  .erp-root .hero-catalog__packet[data-hero-hover-side='human']
    .hero-catalog__panel--human
    .hero-catalog__cta,.erp-root 
  .hero-catalog__packet[data-hero-hover-side='agent']
    .hero-catalog__panel--agent
    .hero-catalog__cta,.erp-root 
  .hero-catalog__panel:focus-within .hero-catalog__cta {
    color: var(--hero-packet-cta-text);
    box-shadow: inset 0 0 0 1px var(--hero-packet-accent);
  }

  .erp-root .hero-catalog__cta:hover::before,.erp-root 
  .hero-catalog__cta:focus-visible::before {
    background-size:
      100% var(--hero-cta-rule-hover),
      100% 100%;
  }

  .erp-root .hero-catalog__packet[data-hero-hover-side='human']
    .hero-catalog__panel--human
    .hero-catalog__cta::before,.erp-root 
  .hero-catalog__packet[data-hero-hover-side='agent']
    .hero-catalog__panel--agent
    .hero-catalog__cta::before,.erp-root 
  .hero-catalog__panel:focus-within .hero-catalog__cta::before {
    background-size:
      100% var(--hero-cta-rule-hover),
      100% 100%;
  }

  .erp-root .hero-catalog__cta:hover svg,.erp-root 
  .hero-catalog__cta:focus-visible svg {
    transform: translateX(0.25rem);
  }

  .erp-root .hero-catalog__cta:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: -0.375rem;
  }

