    justify-content: space-between;
    gap: 16px;
    height: 56px;
  }
  .erp-root .erpnav-left,.erp-root 
  .erpnav-right {
    display: flex;
    align-items: stretch;
  }

  .erp-root .erpnav-brand-wrap {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    padding-right: 16px;
    margin-right: 16px;
    border-right: 1px solid var(--border);
  }
  .erp-root .erpnav-logo {
    display: inline-flex;
    align-items: center;
    color: var(--foreground);
    text-decoration: none;
  }
  .erp-root .erpnav-logo:hover {
