  /* -- Product switcher (shared between erp/crm-subnav) ------------------- */
  .erp-root .ps {
    position: relative;
    display: inline-flex;
    align-items: stretch;
  }
  .erp-root .ps-trigger {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-family: var(--font-heading);
    font-weight: 800;
    font-size: 13px;
    letter-spacing: -0.01em;
    text-transform: uppercase;
    color: var(--foreground);
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;
    text-decoration: none;
  }
  .erp-root .ps-trigger::before {
    content: '';
    display: inline-block;
    width: 6px;
    height: 6px;
    background: var(--red-on-light);
  }
  .erp-root .ps-trigger:hover {
    color: var(--red-on-light);
  }
  .erp-root .ps-menu {
    position: absolute;
    top: calc(100% + 6px);
    left: 0;
    width: 320px;
    background: var(--background);
    border: 1px solid var(--foreground);
    box-shadow: 6px 6px 0 var(--foreground);
    padding: 0;
    display: none;
    z-index: 60;
  }
  /* Transparent hover bridge across the 6px visual gap between the
     trigger and the menu. Without this the cursor leaves `.ps`'s bbox
     mid-traverse, `.ps:hover` flips false, and the menu disappears
     before the cursor reaches the first item. The bridge is a pseudo-
     element on `.ps-menu` (DOM child of `.ps`) so hovering it keeps
     `.ps:hover` active. Same trick used by macOS/iOS dropdown
     vocabulary. */
  .erp-root .ps-menu::before {
    content: '';
    position: absolute;
    top: -6px;
    left: 0;
    right: 0;
    height: 6px;
  }
  .erp-root .ps:hover .ps-menu,.erp-root 
  .ps:focus-within .ps-menu,.erp-root 
  .ps[data-open='true'] .ps-menu {
    display: block;
  }

  .erp-root .ps-menu-head {
    font-family: var(--font-body);
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.18em;
