  .erp-root .ps-menu-head::before {
    content: '● ';
    color: var(--red-on-light);
  }

  .erp-root .ps-app {
    display: grid;
    grid-template-columns: 36px 1fr auto;
    gap: 12px;
    align-items: center;
    padding: 12px 14px;
