    background: var(--accent-yellow);
  }
  .erp-root .ps-app.is-current:hover {
    background: var(--accent-yellow);
    cursor: default;
  }

  .erp-root .ps-app .ps-mono {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border: 1.5px solid var(--foreground);
