    margin: 0 auto;
  }
  .erp-root .compare-row {
    display: grid;
    grid-template-columns: 180px 1fr 1fr;
    border-top: 1px solid var(--border);
  }
  .erp-root .compare-row:first-child {
    border-top: 0;
  }
  @media (max-width: 720px) {
    .erp-root .compare-row {
      grid-template-columns: 1fr;
    }
    .erp-root .compare-cell {
      border-right: 0 !important;
      border-bottom: 1px dashed var(--border);
    }
    .erp-root .compare-cell--label {
      background: var(--surface-dim);
    }
  }
  .erp-root .compare-cell {
    padding: 18px 20px;
    font-family: var(--font-body);
    font-size: 13px;
    line-height: 1.55;
    color: var(--text-m);
    border-right: 1px solid var(--border);
  }
  .erp-root .compare-cell:last-child {
    border-right: 0;
  }
  .erp-root .compare-cell--label {
    font-family: var(--font-heading);
    font-weight: 800;
    text-transform: uppercase;
    font-size: 12px;
    letter-spacing: 0.04em;
    color: var(--foreground);
    background: var(--background);
  }
  .erp-root .compare-cell--old {
    color: var(--text-m);
    background: var(--surface-dim);
    text-decoration: line-through;
    text-decoration-color: oklch(50% 0.005 78 / 0.4);
    text-decoration-thickness: 1px;
  }
  .erp-root .compare-cell--new {
    color: var(--foreground);
    background: var(--background);
    font-weight: 600;
    position: relative;
  }
  /* Tick on the ERP•AI column cells — Tabler `check` SVG injected via
     the .compare-tick span on the template. The header row (no tick
     content) gets the rule below to suppress mistaken styling. */
  .erp-root .compare-cell--new .compare-tick {
    display: inline-flex;
    align-items: center;
    color: var(--red-on-light);
    margin-right: 8px;
    flex-shrink: 0;
  }
  .erp-root .compare-cell--new .compare-tick [data-icon] {
    width: 1em;
    height: 1em;
  }
  .erp-root .compare-head .compare-cell {
    background: var(--foreground);
    color: var(--background);
    font-family: var(--font-body);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    padding: 12px 20px;
    text-decoration: none;
  }
  .erp-root .compare-head .compare-cell--label {
    background: var(--foreground);
  }
  .erp-root .compare-head .compare-cell--new {
    background: var(--accent-yellow);
    color: var(--foreground);
  }

  /* Integrations grid — categorized chip cells */
  .erp-root .integ-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0;
    border: 1px solid var(--border);
    background: var(--background);
  }
  @media (max-width: 900px) {
    .erp-root .integ-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }
  @media (max-width: 540px) {
    .erp-root .integ-grid {
      grid-template-columns: 1fr;
    }
  }
  .erp-root .integ-cell {
    padding: 16px 18px;
    border-right: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
  }
  .erp-root .integ-cell:nth-child(4n) {
    border-right: 0;
  }
  .erp-root .integ-cell:nth-last-child(-n + 4) {
    border-bottom: 0;
  }
  @media (max-width: 900px) {
    .erp-root .integ-cell:nth-child(4n) {
      border-right: 1px solid var(--border);
    }
    .erp-root .integ-cell:nth-child(2n) {
      border-right: 0;
    }
    .erp-root .integ-cell:nth-last-child(-n + 4) {
      border-bottom: 1px solid var(--border);
    }
    .erp-root .integ-cell:nth-last-child(-n + 2) {
      border-bottom: 0;
    }
  }
  .erp-root .integ-cat {
    font-family: var(--font-body);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--foreground);
    margin-bottom: 8px;
  }
  .erp-root .integ-cat .integ-arrow {
    display: inline-flex;
    align-items: center;
    color: var(--red-on-light);
    margin-right: 6px;
    flex-shrink: 0;
  }
  .erp-root .integ-cat .integ-arrow [data-icon] {
    width: 1em;
    height: 1em;
  }
  .erp-root .integ-items {
    font-family: var(--font-body);
    font-size: 11px;
    line-height: 1.5;
    color: var(--text-m);
  }

  /* Mid-page CTA bands — narrow brutalist strip with red border */
  .erp-root .cta-band {
    margin-top: var(--space-10);
    border: 1.5px solid var(--foreground);
    background: var(--background);
    box-shadow: 8px 8px 0 var(--foreground);
    padding: 28px 32px;
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: center;
    gap: 24px;
  }
  @media (max-width: 720px) {
    .erp-root .cta-band {
      grid-template-columns: 1fr;
      box-shadow: 6px 6px 0 var(--foreground);
    }
  }
  .erp-root .cta-band .cta-band-hd {
    font-family: var(--font-heading);
    font-weight: 800;
    text-transform: uppercase;
    font-size: clamp(18px, 1.6vw, 22px);
    letter-spacing: -0.01em;
    color: var(--foreground);
    line-height: 1.15;
  }
  .erp-root .cta-band .cta-band-sub {
    font-family: var(--font-body);
    font-size: 11px;
    letter-spacing: 0.08em;
    color: var(--text-m);
    margin-top: 6px;
  }

  .erp-root .app-section-num {
    font-family: var(--font-body);
    font-size: 13px;
    font-weight: 700;
    color: var(--red-on-light);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border: 1px solid color-mix(in oklab, var(--red-on-light), transparent 75%);
    background: color-mix(in oklab, var(--red-on-light), transparent 92%);
  }
  .erp-root .app-h2 {
    font-family: var(--font-heading);
    font-weight: 700;
    text-transform: none;
    letter-spacing: -0.025em;
    line-height: 0.98;
    color: var(--foreground);
    font-size: var(--text-4xl);
    max-width: 22ch;
    text-wrap: balance;
  }
  .erp-root .app-italic {
    font-family: var(--font-serif);
    font-style: italic;
    color: var(--red-on-light);
    font-size: var(--text-xl);
    line-height: 1.25;
    text-wrap: pretty;
  }
  @media (min-width: 1024px) {
    .erp-root .app-h2 {
      font-size: var(--text-5xl);
    }
    .erp-root .app-italic {
      font-size: var(--text-2xl);
    }
  }

  /* Per-section hero header — every section gets the same centered
     "hero" treatment: index chip → big h2 → italic subline → optional CTA. */
  .erp-root .section-hero {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    margin: 0 auto var(--space-12);
    max-width: 880px;
    gap: 18px;
  }
  .erp-root .section-hero .sh-chip {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    font-family: var(--font-body);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--text-m);
  }
  .erp-root .section-hero .sh-chip .sh-num {
    background: var(--foreground);
    color: var(--background);
    padding: 3px 8px 4px;
    font-size: 11px;
    letter-spacing: 0.1em;
  }
  .erp-root .section-hero .app-h2 {
    max-width: 24ch;
    margin: 0 auto;
  }
  .erp-root .section-hero .app-italic {
    max-width: 70ch;
    margin: 0 auto;
  }
  .erp-root .section-hero-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    justify-content: center;
    margin-top: 8px;
  }
  /* When an entire section's *body* should be center-aligned too */
  .erp-root .app-section-centered {
    text-align: center;
  }
  .erp-root .app-section-centered .grid-cards {
    text-align: left;
  }
  .erp-root .app-section-centered .loop-step {
    text-align: left;
  }
  .erp-root .app-section-centered details.faq-item {
    text-align: left;
  }

  /* Stat band */
  .erp-root .app-stats {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
    background: var(--background);
  }
  /* 6 cols only ≥1281px — below that 6 equal tracks crush the mono
     copy (number + ticks overflow into the next card). 6 is clean at
     6/3/2/1, so step straight to 3 (two rows of three). */
  @media (max-width: 1280px) {
    .erp-root .app-stats {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }
  }
  @media (max-width: 600px) {
    .erp-root .app-stats {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }
  @media (max-width: 420px) {
    .erp-root .app-stats {
      grid-template-columns: 1fr;
    }
  }
  .erp-root .app-stat {
    position: relative;
    padding: 22px 20px 20px;
    border-right: 1px solid var(--border);
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-height: 168px;
  }
  .erp-root .app-stat:last-child {
    border-right: 0;
  }
  @media (max-width: 1280px) {
    .erp-root .app-stat:nth-child(3n) {
      border-right: 0;
    }
    .erp-root .app-stat:nth-child(n + 4) {
      border-top: 1px solid var(--border);
    }
  }
  @media (max-width: 600px) {
    .erp-root .app-stat {
      border-right: 1px solid var(--border);
    }
    .erp-root .app-stat:nth-child(3n) {
      border-right: 1px solid var(--border);
    }
    .erp-root .app-stat:nth-child(2n) {
      border-right: 0;
    }
    .erp-root .app-stat:nth-child(n + 3) {
      border-top: 1px solid var(--border);
    }
  }
  @media (max-width: 420px) {
    .erp-root .app-stat,.erp-root 
    .app-stat:nth-child(2n),.erp-root 
    .app-stat:nth-child(3n) {
      border-right: 0;
    }
    .erp-root .app-stat:nth-child(n + 2) {
      border-top: 1px solid var(--border);
    }
  }
  .erp-root .app-stat .eyebrow {
    font-family: var(--font-body);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--text-m);
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .erp-root .app-stat .eyebrow::before {
    content: attr(data-idx);
    background: var(--foreground);
    color: var(--background);
    padding: 2px 6px 3px;
    font-size: 9px;
    letter-spacing: 0.1em;
  }
  .erp-root .app-stat .v {
    position: relative;
    isolation: isolate;
    font-family: var(--font-heading);
    font-weight: 700;
    font-size: clamp(36px, 4vw, 56px);
    color: var(--foreground);
    letter-spacing: -0.04em;
    line-height: 0.9;
    display: inline-block;
    align-self: flex-start;
    padding: 0 4px;
  }
  .erp-root .app-stat .v::before {
    content: '';
    position: absolute;
    left: -2px;
    right: -2px;
    bottom: 6px;
    height: 16px;
    background: var(--accent-yellow);
    z-index: -1;
    transform: skewX(-6deg);
  }
  .erp-root .app-stat .v sup {
    font-size: 0.4em;
    font-weight: 700;
    color: var(--text-m);
    margin-left: 2px;
    letter-spacing: 0;
    vertical-align: top;
    top: 0.4em;
    position: relative;
  }
  .erp-root .app-stat .l {
    font-family: var(--font-heading);
    font-weight: 700;
    font-size: 14px;
    line-height: 1.15;
    text-transform: none;
    letter-spacing: -0.005em;
    color: var(--foreground);
  }
  .erp-root .app-stat .sub {
    font-family: var(--font-body);
    font-size: 10px;
    line-height: 1.4;
    letter-spacing: 0.04em;
    color: var(--text-m);
    margin-top: auto;
  }
  .erp-root .app-stat .ticks {
    display: flex;
    gap: 2px;
    margin-top: 6px;
    height: 8px;
    align-items: stretch;
  }
  .erp-root .app-stat .ticks span {
    flex: 1;
    background: var(--foreground);
    opacity: 0.18;
  }
  .erp-root .app-stat .ticks span.on {
    opacity: 1;
  }
  .erp-root .app-stat .ticks.dense span {
    flex: none;
    width: 3px;
  }
  /* Per-cell glyph in top-right */
  .erp-root .app-stat .mark {
    position: absolute;
    top: 18px;
    right: 18px;
    font-family: var(--font-body);
    font-size: 11px;
    font-weight: 700;
    color: var(--text-m);
    opacity: 0.7;
    letter-spacing: 0;
  }

  /* Card grids */
  /* Card-lattice grid. Column count is now driven here (not via an
     inline style on each section) so it can step down with viewport
     width. The cells carry border-right/border-bottom and the
     container closes the outer edge, so uneven trailing rows still
     read as a clean lattice. Mono body copy needs ~300px of column
     to avoid the ragged 6-line wrap seen on /erp-enterprise §03. */
  .erp-root .grid-cards {
    display: grid;
    gap: 0;
    border: 1px solid var(--border);
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  @media (max-width: 1280px) {
    .erp-root .grid-cards {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }
  }
  @media (max-width: 960px) {
    .erp-root .grid-cards {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }
  @media (max-width: 620px) {
    .erp-root .grid-cards {
      grid-template-columns: 1fr;
    }
  }
  .erp-root .pp-card {
    padding: var(--space-6);
    border-right: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
    background: var(--background);
  }
  /* .card-tag — consolidated rule. The page originally declared two
     rule blocks (the second with !important markers to win against the
     first). Now collapsed to one rule with the !important-winning
     property set. The !important markers stay as documentation of the
     original intent; a future PR can clean them up alongside the
     .product-page card-cell vocab refresh. */
  /* "Agent" tag (§03 only) — demoted from a solid dark chip to a
     muted mono-caps label so the monogram chip + tag + title read as
     a clean eyebrow → headline hierarchy (same vocabulary as the
     section eyebrow's label). */
  .erp-root .pp-card .card-tag {
    font-family: var(--font-body);
    text-transform: uppercase;
    margin-bottom: var(--space-2);
    display: inline-block !important;
    width: auto !important;
    color: var(--text-m) !important;
    background: transparent !important;
    padding: 0 !important;
    align-self: flex-start;
    font-size: 11px !important;
    font-weight: 700;
    letter-spacing: 0.18em !important;
  }
  .erp-root .pp-card .card-title {
    font-family: var(--font-heading);
    font-weight: 700;
    font-size: 18px;
    text-transform: none;
    letter-spacing: -0.01em;
    color: var(--foreground);
    margin-bottom: var(--space-3);
  }
  .erp-root .pp-card .card-divider {
    height: 1px;
    background: var(--border);
    margin-bottom: var(--space-3);
  }
  .erp-root .pp-card .card-body {
    font-family: var(--font-body);
    font-size: 11px;
    line-height: 1.55;
    color: var(--text-m);
  }

  /* The loop — flow steps */
  .erp-root .loop-step {
    display: grid;
    grid-template-columns: 60px minmax(0, 1fr) 320px;
    gap: var(--space-6);
    padding: var(--space-6) 0;
    border-top: 1px dashed var(--border);
    align-items: start;
  }
  @media (max-width: 960px) {
    .erp-root .loop-step {
      grid-template-columns: 60px 1fr;
    }
    .erp-root .loop-step .je-chip {
      grid-column: 2 / -1;
      max-width: 320px;
    }
  }
  @media (max-width: 520px) {
    .erp-root .loop-step {
      grid-template-columns: 1fr;
      gap: var(--space-3);
    }
    .erp-root .loop-step .je-chip {
      grid-column: 1 / -1;
      max-width: 100%;
    }
  }
  .erp-root .loop-step:first-of-type {
    border-top: 0;
  }
  .erp-root .loop-step .num {
    font-family: var(--font-heading);
    font-weight: 700;
    font-size: 28px;
    letter-spacing: -0.04em;
    color: var(--red-on-light);
    line-height: 1;
  }
  /* h3 (CRM) + h4 (ERP) both render as the step-body heading — consolidated. */
  .erp-root .loop-step .body h3,.erp-root 
  .loop-step .body h4 {
    font-family: var(--font-heading);
    text-transform: none;
    font-weight: 700;
    font-size: 18px;
    letter-spacing: -0.015em;
    line-height: 1.1;
    color: var(--foreground);
    margin: 0 0 var(--space-2);
  }
  .erp-root .loop-step .body p {
    font-family: var(--font-body);
    font-size: 14px;
    line-height: 1.55;
    color: var(--text-m);
    margin: 0;
    max-width: 60ch;
  }

  /* JE T-account chip — the posting that step generates (ERP) / the state
     transition each step fires (CRM). Reinforces "one ledger" / "one record"
     by showing the downstream artifact at every step. */
  .erp-root .je-chip {
    border: 1px solid var(--foreground);
    background: var(--background);
    box-shadow: 4px 4px 0 var(--foreground);
    font-family: var(--font-body);
    font-size: 11px;
    width: 100%;
  }
  @media (max-width: 520px) {
    .erp-root .je-chip {
      box-shadow: none;
    }
  }
  .erp-root .je-chip .je-hd {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 10px;
    background: var(--foreground);
    color: var(--background);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
  }
  .erp-root .je-chip .je-hd .je-tag {
    background: var(--accent-yellow);
    color: var(--foreground);
    padding: 1px 5px;
    font-size: 9px;
  }
  .erp-root .je-chip .je-hd .je-tag--muted {
    background: transparent;
    color: var(--background);
    border: 1px solid var(--background);
  }
  .erp-root .je-chip .je-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .erp-root .je-chip .je-col {
    padding: 8px 10px;
  }
  .erp-root .je-chip .je-col + .je-col {
    border-left: 1px solid var(--border);
  }
  .erp-root .je-chip .je-col-hd {
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--text-m);
    margin-bottom: 4px;
  }
  .erp-root .je-chip .je-row {
    display: flex;
    justify-content: space-between;
    gap: 8px;
    color: var(--foreground);
    line-height: 1.4;
  }
  .erp-root .je-chip .je-row + .je-row {
    margin-top: 2px;
  }
  .erp-root .je-chip .je-row .je-acct {
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .erp-root .je-chip .je-row .je-amt {
    color: var(--text-m);
    font-variant-numeric: tabular-nums;
  }
  .erp-root .je-chip .je-foot {
    padding: 6px 10px;
    border-top: 1px solid var(--border);
    font-size: 10px;
    color: var(--text-m);
    letter-spacing: 0.04em;
  }
  /* Non-posting step: single-cell info badge */
  .erp-root .je-chip--info {
    background: var(--background);
  }
  .erp-root .je-chip--info .je-grid {
    grid-template-columns: 1fr;
  }
  .erp-root .je-chip--info .je-col + .je-col {
    border-left: none;
    border-top: 1px solid var(--border);
  }

  /* FAQ */
  .erp-root details.faq-item {
    border-top: 1px solid var(--border);
    padding: var(--space-4) 0;
  }
  .erp-root details.faq-item:last-of-type {
    border-bottom: 1px solid var(--border);
  }
  .erp-root details.faq-item summary {
    cursor: pointer;
    list-style: none;
    font-family: var(--font-heading);
    text-transform: uppercase;
    font-weight: 800;
    font-size: 16px;
    letter-spacing: -0.01em;
    color: var(--foreground);
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: var(--space-4);
  }
  .erp-root details.faq-item summary::-webkit-details-marker {
    display: none;
  }
  .erp-root details.faq-item summary::after {
    content: '+';
    font-family: var(--font-body);
    color: var(--red-on-light);
    font-size: 24px;
    line-height: 1;
  }
  .erp-root details.faq-item[open] summary::after {
    content: '–';
  }
  .erp-root details.faq-item p {
    font-family: var(--font-body);
    font-size: 15px;
    line-height: 1.6;
    color: var(--text-m);
    margin: var(--space-3) 0 0;
    max-width: 75ch;
  }

  /* Real screenshot frame */
  .erp-root .app-shot {
    margin: 0 auto;
    max-width: 1100px;
    border: 1px solid var(--border);
    background: var(--background);
    box-shadow: 8px 8px 0 var(--text-d);
    padding: 0;
  }
  .erp-root .app-shot img {
    display: block;
