  .erp-root:not(.dark) .site-footer--tacet .site-footer__logo::before,.erp-root:not(.dark) .site-footer--tacet .site-footer__badge-icon::before,.erp-root:not(.dark) .site-footer--tacet .site-footer__social a::before {
