  /* -- Design system reference -------------------------------------------- */
  .erp-root {
    --tacet-accent-text: var(--tacet-orange-on-light);
    --ds-accent-text: var(--tacet-accent-text);
  }
  html:has(.erp-root) {
    --tacet-accent-text: var(--tacet-orange-on-light);
    --ds-accent-text: var(--tacet-accent-text);
  }

  .erp-root.dark {
    --tacet-accent-text: var(--tacet-orange);
    --ds-accent-text: var(--tacet-accent-text);
  }

  html:has(.erp-root.dark) {
    --tacet-accent-text: var(--tacet-orange);
    --ds-accent-text: var(--tacet-accent-text);
  }

  .erp-root .tacet-design-system-page .ds-section {
    scroll-margin-top: calc(var(--tacet-page-nav-height) + var(--space-4));
  }

  .erp-root .ds-wrap {
    width: min(100%, 90rem);
    margin-inline: auto;
    padding-inline: var(--space-6);
  }

  .erp-root .ds-section__header > span,.erp-root 
  .ds-spec-card__meta,.erp-root 
  .ds-rule-grid article > span,.erp-root 
  .ds-card-demo article > span,.erp-root 
  .ds-icon-grid article > span,.erp-root 
  .ds-card-type > span,.erp-root 
  .ds-hero-type > span {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-family: var(--font-body);
    font-size: var(--fs-chip);
    font-weight: 700;
    letter-spacing: 0.15em;
    line-height: 1;
    text-transform: uppercase;
    color: var(--ds-accent-text);
  }

  .erp-root .ds-section__header h2 {
    max-width: 16ch;
    font-family: var(--font-heading);
    font-size: var(--fs-section);
    font-weight: 900;
    line-height: 0.9;
    letter-spacing: -0.03em;
    text-transform: none;
