  /* -- Not-found recovery page ------------------------------------------- */
  .erp-root .tacet-not-found-page {
    background: var(--background);
  }

  .erp-root .not-found {
    position: relative;
    isolation: isolate;
    display: grid;
    min-height: calc(100svh - var(--chrome-height));
    place-items: center;
    overflow: hidden;
    padding: clamp(8.5rem, 15vh, 11rem) var(--tacet-section-pad-x) clamp(4rem, 8vh, 6rem);
    background:
      linear-gradient(color-mix(in oklab, var(--border), transparent 62%) 1px, transparent 1px),
      linear-gradient(
        90deg,
        color-mix(in oklab, var(--border), transparent 62%) 1px,
        transparent 1px
      ),
      var(--background);
    background-size: clamp(3rem, 7vw, 6rem) clamp(3rem, 7vw, 6rem);
  }

  .erp-root .not-found::before {
    position: absolute;
    z-index: -1;
    width: min(70vw, 58rem);
    aspect-ratio: 1;
    border: 1px solid color-mix(in oklab, var(--org), transparent 78%);
    background: radial-gradient(
      circle,
      color-mix(in oklab, var(--org), transparent 87%),
      transparent 68%
    );
    content: '';
    filter: blur(1px);
    pointer-events: none;
    transform: rotate(22deg) translate(28%, 2%);
  }

  .erp-root .not-found__frame {
    display: grid;
    width: var(--tacet-visible-rail);
    max-width: calc(var(--tacet-section-max) - (2 * var(--tacet-section-pad-x)));
    grid-template-columns: minmax(0, 0.86fr) minmax(28rem, 1.14fr);
    border-block: 1px solid var(--border-strong);
    background: color-mix(in oklab, var(--background), transparent 5%);
  }

  .erp-root .not-found__copy {
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding: clamp(2.5rem, 6vw, 5.75rem) clamp(1rem, 5vw, 4.75rem) clamp(2.5rem, 6vw, 5.75rem) 0;
  }

  .erp-root .not-found-route__header,.erp-root 
  .not-found-route__footer,.erp-root 
  .not-found-route__label,.erp-root 
  .not-found__assurance {
    font-family: var(--font-mono);
  }

  .erp-root .not-found__copy > .proto-section-eyebrow {
    position: absolute;
    top: -1px;
    left: 0;
    margin: 0;
    padding-top: var(--space-2);
    width: min(12rem, 100%);
    border-top: 2px solid var(--org-on-light);
  }

  .erp-root .not-found h1 {
    max-width: 10ch;
    margin: 0;
    color: var(--foreground);
    font-family: var(--font-heading);
    font-size: clamp(3.4rem, 6.7vw, 6.65rem);
    font-weight: 700;
    letter-spacing: var(--tacet-type-hero-track);
    line-height: 0.9;
  }

  .erp-root .not-found__lede {
    max-width: 34rem;
    margin: clamp(1.5rem, 3vw, 2.25rem) 0 0;
    color: var(--text-m);
    font-family: var(--font-body);
    font-size: clamp(1rem, 1.5vw, 1.1875rem);
    line-height: 1.65;
  }

  .erp-root .not-found__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-top: clamp(2rem, 4vw, 2.75rem);
  }

  .erp-root .not-found__assurance {
    margin: 1.25rem 0 0;
    color: var(--text-m);
    font-size: 0.6875rem;
    letter-spacing: 0.02em;
  }

  .erp-root .not-found-route {
    min-width: 0;
    margin: 0;
    border-left: 1px solid var(--border-strong);
    background: color-mix(in oklab, var(--surface-raised), transparent 16%);
  }

  .erp-root .not-found-route__header,.erp-root 
  .not-found-route__footer {
    display: flex;
    min-height: 3rem;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding-inline: clamp(1rem, 3vw, 1.75rem);
    color: var(--text-m);
    font-size: 0.625rem;
    letter-spacing: 0.11em;
  }

  .erp-root .not-found-route__header {
    border-bottom: 1px solid var(--border);
  }

  .erp-root .not-found-route__header span:last-child {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
  }

  .erp-root .not-found-route__header i {
    width: 0.5rem;
    height: 0.5rem;
    background: var(--org-on-light);
    border-radius: 50%;
    box-shadow: 0 0 0 0.25rem color-mix(in oklab, var(--org), transparent 82%);
  }

  .erp-root .not-found-route__canvas {
    position: relative;
    min-height: clamp(26rem, 46vw, 34rem);
    overflow: hidden;
  }

  .erp-root .not-found-route__numeral {
    position: absolute;
    inset: 50% auto auto 50%;
    color: transparent;
    font-family: var(--font-heading);
    font-size: clamp(10rem, 24vw, 20rem);
    font-weight: 700;
    letter-spacing: var(--tacet-type-hero-track);
    line-height: 0.75;
    opacity: 0.48;
    pointer-events: none;
    transform: translate(-52%, -54%);
    white-space: nowrap;
    -webkit-text-stroke: 1px color-mix(in oklab, var(--foreground), transparent 77%);
  }

  .erp-root .not-found-route__diagram {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    overflow: visible;
    pointer-events: none;
  }

  .erp-root .not-found-route__grid-line {
    fill: none;
    stroke: color-mix(in oklab, var(--border), transparent 32%);
    stroke-width: 1;
  }

  .erp-root .not-found-route__base,.erp-root 
  .not-found-route__trace {
    fill: none;
    stroke-linecap: square;
    stroke-linejoin: miter;
  }

  .erp-root .not-found-route__base {
    stroke: color-mix(in oklab, var(--foreground), transparent 74%);
    stroke-dasharray: 3 8;
    stroke-width: 2;
  }

  .erp-root .not-found-route__trace {
    stroke: var(--org-on-light);
    stroke-dasharray: 1;
    stroke-dashoffset: 0;
    stroke-width: 4;
  }

  .erp-root .not-found-route__origin {
    fill: var(--background);
    stroke: var(--foreground);
    stroke-width: 3;
  }

  .erp-root .not-found-route__break circle {
    fill: var(--background);
    stroke: var(--org-on-light);
    stroke-width: 2;
  }

  .erp-root .not-found-route__break path {
    fill: none;
    stroke: var(--org-on-light);
    stroke-width: 3;
  }

  .erp-root .not-found-route__label {
    position: absolute;
    padding: 0.4rem 0.5rem;
    border: 1px solid var(--border);
    background: var(--background);
    color: var(--foreground);
    font-size: 0.625rem;
    letter-spacing: 0.02em;
    line-height: 1.2;
    text-decoration: none;
    white-space: nowrap;
  }

  .erp-root .not-found-route__label--origin {
    top: 55%;
    left: 3%;
  }

  .erp-root .not-found-route__endpoint {
    position: absolute;
    z-index: 2;
    width: 2.75rem;
    height: 2.75rem;
    color: var(--foreground);
    transform: translate(-50%, -50%);
  }

  .erp-root .not-found-route__endpoint--home {
    top: 29.1667%;
    left: 90%;
  }

  .erp-root .not-found-route__endpoint--catalog {
    top: 48.3333%;
    left: 90%;
  }

  .erp-root .not-found-route__endpoint-marker {
    position: absolute;
    inset: 0;
    border: 2px solid var(--org-on-light);
    border-radius: 50%;
  }

  .erp-root .not-found-route__endpoint-marker::after {
    position: absolute;
    inset: 50% auto auto 50%;
    width: 1.375rem;
    height: 1.375rem;
    background: var(--org-on-light);
    border-radius: 50%;
    content: '';
    transform: translate(-50%, -50%);
  }

  .erp-root .not-found-route__endpoint .not-found-route__label {
    right: -0.5rem;
    bottom: calc(100% + 0.625rem);
  }

  .erp-root .not-found-route__endpoint:is(:hover, :focus-visible) .not-found-route__label {
    border-color: var(--border-strong);
  }

  .erp-root .not-found-route__endpoint:focus-visible {
    border-radius: 50%;
    outline: 2px solid var(--foreground);
    outline-offset: 4px;
  }

  .erp-root .not-found-route__footer {
    border-top: 1px solid var(--border);
  }

  @keyframes not-found-route-trace {
    0% {
      stroke-dashoffset: 1;
    }

    72%,
    100% {
      stroke-dashoffset: 0;
    }
  }

  @keyframes not-found-route-arrive {
    0%,
    68% {
      opacity: 0;
      transform: scale(0.6);
    }

    82%,
    100% {
      opacity: 1;
      transform: scale(1);
    }
  }

  @media (prefers-reduced-motion: no-preference) {
    .erp-root .not-found-route__trace {
      animation: not-found-route-trace 5s var(--ease-expo-in-out) both;
    }

    .erp-root .not-found-route__trace--branch {
      animation-delay: 0.5s;
    }

    .erp-root .not-found-route__endpoint-marker {
      transform-origin: center;
      animation: not-found-route-arrive 5s var(--ease-expo-in-out) both;
    }

    .erp-root .not-found-route__endpoint--home .not-found-route__endpoint-marker {
      animation-delay: 0.5s;
    }
  }

  @media (max-width: 64rem) {
    .erp-root .not-found__frame {
      grid-template-columns: minmax(0, 1fr);
    }

    .erp-root .not-found__copy {
      padding: 6.5rem 0 3.5rem;
