    .erp-root .tacet-proto-motion--hero {
      margin-top: var(--space-6);
    }

    .erp-root .tacet-proto-story__copy h2 {
      font-size: clamp(2rem, 10vw, 3rem);
    }

    .erp-root .tacet-proto-story__media {
      padding: var(--space-3);
    }

    .erp-root .tacet-proto-bulletin-grid {
      grid-template-columns: 1fr;
    }
  }
  /* Muted labels here are set small (HUD, gauge, records, collage captions);
     dark mode lifts them to the mid ink so they hold 4.5:1 on the page. */
  .erp-root.dark .tacet-about-page {
    --muted-foreground: var(--ink-light-mid);
  }

  .erp-root.dark :is(.tacet-about-page, .tacet-evals-page) {
    --about-dixit: oklch(66% 0.1 82);
    --about-mark: oklch(62% 0.1 95 / 0.5);
  }

  /* Each level of the dive has its own field, in muted print tones held to
     a similar strength so no one of them shouts: terracotta for the cover
     (Tacet orange, toned down), oxblood for Steve, ochre for Shashank,
     slate for Somesh. Cream papers carry the content; the fields are
     ground. */
  .erp-root :is(.tacet-about-page, .tacet-evals-page) {
    --about-erpai: oklch(64% 0.13 48);
    --about-papa: oklch(44% 0.1 20);
    --about-dixit: oklch(74% 0.1 82);
    --about-misra: oklch(46% 0.06 240);
    --about-dixit-ink: oklch(56% 0.1 80);
    --about-mark: oklch(90% 0.12 100 / 0.7);
  }

  .erp-root .tacet-about-page {
    --dive-nav: 4.5rem;
    --dive-hud: 5.5rem;
    --dive-gap: 4rem;
    --dive-avail: calc(100svh - var(--dive-nav) - var(--dive-hud) - 1.5rem);
    --dive-frame-h: min(calc(var(--dive-avail) - 2.5rem), calc((100vw - 2rem) * 1.25));
  }

  .erp-root .tacet-about-page .about {
