  }

  .erp-root .tacet-about-page .about-row--refs a {
    color: var(--foreground);
    text-decoration: underline;
    text-underline-offset: 3px;
  }

  /* -- Collage ------------------------------------------------------------ */

  .erp-root .tacet-about-page .about-defs {
    position: absolute;
    width: 0;
    height: 0;
    overflow: hidden;
  }

  .erp-root .about-ground {
    fill: var(--surface-dim);
  }

  .erp-root .about-ground--erpai {
    fill: var(--about-erpai);
  }

  .erp-root .about-ground--papa {
    fill: var(--about-papa);
  }

  .erp-root .about-ground--dixit {
    fill: var(--about-dixit);
  }

  .erp-root .about-ground--misra {
    fill: var(--about-misra);
  }

  .erp-root .about-portal-margin {
    fill: none;
    stroke: var(--background);
    stroke-width: 6;
    vector-effect: non-scaling-stroke;
  }

  .erp-root .about-portal {
    fill: none;
    stroke: var(--foreground);
    stroke-width: 1.5;
    vector-effect: non-scaling-stroke;
  }

  .erp-root .about-portal-tab {
    font-family: var(--font-body);
    font-size: 26px;
    font-weight: 600;
    text-anchor: end;
    fill: var(--foreground);
    paint-order: stroke;
    stroke: var(--background);
    stroke-width: 7px;
    stroke-linejoin: round;
    transition: opacity var(--duration-fast, 150ms) ease;
  }

  .erp-root .about-fixed-point {
    fill: var(--org-on-light);
    stroke: var(--background);
    stroke-width: 2;
  }

  /* The ring and its label mark p once the dive reaches its last chapter. */
  .erp-root .about-fixed-ring {
    transform-box: fill-box;
    transform-origin: center;
    fill: none;
    stroke: var(--org-on-light);
    stroke-width: 1.5;
    opacity: 0;
    transition: opacity var(--duration-slow, 400ms) ease;
  }

  .erp-root .about-fixed-label {
    font-family: var(--font-voice);
    font-size: 16px;
    font-style: italic;
    font-weight: 600;
    fill: var(--org-on-light);
    opacity: 0;
    transition: opacity var(--duration-slow, 400ms) ease;
  }

  /* A level's name tab hides while the level fills the frame; the HUD names
     it then, and the tab would sit under the nav. */
  .erp-root .dive__level--framed > .about-portal-tab {
    opacity: 0;
  }

  .erp-root .dive--at-p .about-fixed-ring,.erp-root 
  .dive--at-p .about-fixed-label {
    opacity: 1;
  }

  .erp-root .about-math {
    font-family: var(--font-voice);
    font-size: 15px;
    font-style: italic;
    font-variant-ligatures: none;
    fill: var(--foreground);
  }

  .erp-root .about-mono,.erp-root 
  .about-math {
    white-space: pre;
  }

  .erp-root .about-initials {
    font-family: var(--font-heading);
    font-size: 300px;
    font-weight: 700;
    fill: none;
    stroke: color-mix(in oklab, var(--beige-50) 55%, transparent);
    stroke-width: 1.5;
  }

  .erp-root .about-paper {
    stroke: var(--foreground);
    stroke-width: 1;
  }

  .erp-root .about-paper--light {
    fill: var(--background);
  }

  .erp-root .about-paper--mid {
    fill: var(--surface-container);
  }

  .erp-root .about-paper--dim {
    fill: var(--surface-dim);
  }

  .erp-root .about-halftone {
    fill: url('#about-halftone-dots');
  }

  .erp-root .about-dot {
    fill: var(--muted-foreground);
    fill-opacity: 0.35;
  }

  .erp-root .about-mono {
    font-family: var(--font-mono);
    font-size: 10px;
  }

  .erp-root .about-small {
    font-size: 9px;
  }

  .erp-root .about-strong {
    font-weight: 700;
  }

  .erp-root .about-num {
    text-anchor: end;
    font-variant-numeric: tabular-nums;
  }

  .erp-root .about-ink,.erp-root 
  .about-ink-fill {
    fill: var(--foreground);
  }

  .erp-root .about-muted {
    fill: var(--muted-foreground);
  }

  .erp-root .about-accent-fill {
    fill: var(--primary);
  }

  .erp-root .about-eq {
    font-family: var(--font-heading);
    font-size: 17px;
    font-weight: 700;
    fill: var(--foreground);
  }

  .erp-root .about-rule,.erp-root 
  .about-edges line,.erp-root 
  .about-edges polyline,.erp-root 
  .about-wire,.erp-root 
  .about-axis {
    fill: none;
    stroke: var(--foreground);
    stroke-width: 1;
  }

  .erp-root .about-axis {
    stroke-width: 1.5;
  }

  .erp-root .about-rule--faint {
    stroke: var(--border-strong);
  }

  .erp-root .about-rule--dash {
    stroke-dasharray: 3 3;
  }

  .erp-root .about-node-open circle {
    fill: var(--background);
    stroke: var(--foreground);
    stroke-width: 1;
  }

  .erp-root .about-box {
    fill: none;
    stroke: var(--foreground);
    stroke-width: 1;
  }

  .erp-root .about-box--on {
    fill: var(--foreground);
  }

  .erp-root .about-box--fill {
    fill: var(--background);
  }

  .erp-root .about-initials--wide {
    font-size: 196px;
  }

  /* Seven reuse channels, N = 7. */
  .erp-root .about-ch-0 {
    --i: 0;
    --about-ch: var(--about-erpai);
  }

  .erp-root .about-ch-1 {
    --i: 1;
    --about-ch: var(--about-papa);
  }

  .erp-root .about-ch-2 {
    --i: 2;
    --about-ch: var(--about-dixit);
  }

  .erp-root .about-ch-3 {
    --i: 3;
    --about-ch: var(--about-misra);
  }

  .erp-root .about-ch-4 {
    --i: 4;
    --about-ch: var(--background);
  }

  .erp-root .about-ch-5 {
    --i: 5;
    --about-ch: var(--beige-500);
  }

  .erp-root .about-ch-6 {
    --i: 6;
    --about-ch: var(--foreground);
  }

  .erp-root .about-bar-track {
    fill: var(--background);
    stroke: var(--foreground);
    stroke-width: 0.75;
  }

  .erp-root .about-bar--frozen {
    fill: var(--about-misra);
  }

  .erp-root .about-bar--raw {
    fill: var(--about-erpai);
  }

  .erp-root .about-curve {
    fill: none;
    stroke: var(--foreground);
    stroke-width: 2;
  }

  .erp-root .about-curve--faint {
    stroke: var(--muted-foreground);
    stroke-width: 1.5;
    stroke-dasharray: 4 3;
  }

  .erp-root .about-stamp {
    fill: var(--background);
    fill-opacity: 0.75;
    stroke: var(--about-stamp, var(--foreground));
    stroke-width: 2.5;
  }

  .erp-root .about-stamp--inner {
    fill: none;
    stroke-width: 1;
  }

  .erp-root .about-stamp-text {
    font-family: var(--font-heading);
    font-size: 12px;
    font-weight: 700;
    text-anchor: middle;
    fill: var(--about-stamp, var(--foreground));
  }

  .erp-root .about-stamp-ink--cobalt {
    --about-stamp: var(--about-misra);
  }

  .erp-root .about-stamp-ink--cherry {
    --about-stamp: var(--about-papa);
  }

  .erp-root .about-stamp-text--year {
    font-size: 16px;
  }

  .erp-root .about-stamp-text--small {
    font-family: var(--font-body);
    font-size: 9px;
    font-weight: 600;
  }

  /* Clippings sit at fixed angles inside each base collage. */

  .erp-root .about-rot-m12 {
    --about-rot: -12deg;
  }

  .erp-root .about-rot-m10 {
    --about-rot: -10deg;
  }

  .erp-root .about-rot-m4 {
    --about-rot: -4deg;
  }

  .erp-root .about-rot-m3 {
    --about-rot: -3deg;
  }

  .erp-root .about-rot-m2 {
    --about-rot: -2deg;
  }

  .erp-root .about-rot-p2 {
    --about-rot: 2deg;
  }

  .erp-root .about-rot-p3 {
    --about-rot: 3deg;
  }

  .erp-root .about-rot-p4 {
    --about-rot: 4deg;
  }

  /* -- Scene motion --------------------------------------------------------
     Every clipping sways a little about its own angle, and each collage has
     one or two working parts: the request path advances, the audit log
     writes, the reuse channels take turns, packets cross the edge map, the
     parts tree draws, the loss curve traces, attention runs token by token,
     the scores fill, and the stamps come down. Animations exist only on
     levels near the frame's size (--a-* names, set by the level classes
     about-droste.js toggles); elsewhere their names resolve to none, so
     Chrome keeps no compositing layers for them. */

  .erp-root .about-frag {
    transform-box: fill-box;
    transform-origin: center;
    transform: rotate(var(--about-rot, 0deg));
    animation: 7s ease-in-out infinite alternate;
    animation-name: var(--a-sway, none);
  }

  .erp-root .about-frag:nth-of-type(2n) {
    animation-duration: 8.5s;
    animation-delay: -3s;
  }

  .erp-root .about-frag:nth-of-type(3n) {
    animation-duration: 6s;
    animation-delay: -1.5s;
  }

  @keyframes about-sway {
    from {
      transform: rotate(calc(var(--about-rot, 0deg) - 0.8deg));
    }

    to {
      transform: rotate(calc(var(--about-rot, 0deg) + 0.8deg));
    }
  }

  /* Stagger index for the scene animations. */
  .erp-root .about-i0 {
    --i: 0;
  }

  .erp-root .about-i1 {
    --i: 1;
  }

  .erp-root .about-i2 {
    --i: 2;
  }

  .erp-root .about-i3 {
    --i: 3;
  }

  .erp-root .about-i4 {
    --i: 4;
  }

  .erp-root .about-i5 {
    --i: 5;
  }

  .erp-root .about-i6 {
    --i: 6;
  }

  .erp-root .about-i7 {
    --i: 7;
  }

  .erp-root .about-step {
    animation: 5s infinite;
    animation-name: var(--a-step, none);
    animation-delay: calc(var(--i, 0) * 0.6s);
  }

  @keyframes about-step {
    0%,
    62% {
      fill: var(--about-erpai);
    }

    70%,
    100% {
      fill: var(--background);
    }
  }

  .erp-root .about-logline {
    animation: 6s infinite;
    animation-name: var(--a-log, none);
    animation-delay: calc(var(--i, 0) * 0.7s);
  }

  @keyframes about-log {
    0% {
      opacity: 0;
    }

    4%,
    88% {
      opacity: 1;
    }

    96%,
    100% {
      opacity: 0;
    }
  }

  .erp-root .about-mark {
    fill: var(--about-mark);
    transform-box: fill-box;
    transform-origin: left center;
    animation: 5.5s ease-out infinite;
    animation-name: var(--a-mark, none);
  }

  @keyframes about-mark {
    0% {
      transform: scaleX(0);
    }

    18%,
    86% {
      transform: scaleX(1);
    }

    100% {
      transform: scaleX(0);
    }
  }

  /* The channels transmit in turn: co-channel cells flash to ink together. */
  .erp-root .about-hex {
    fill: var(--about-ch, none);
    stroke: var(--foreground);
    stroke-width: 1;
    animation: 4.2s infinite;
    animation-name: var(--a-channel, none);
    animation-delay: calc(var(--i, 0) * 0.6s);
  }

  @keyframes about-channel {
    0%,
    10% {
      fill: var(--background);
    }

    18%,
    100% {
      fill: var(--about-ch, none);
    }
  }

  .erp-root .about-flow line {
    stroke-dasharray: 2 4;
    animation: 1.4s linear infinite;
    animation-name: var(--a-flow, none);
  }

  @keyframes about-flow {
    to {
      stroke-dashoffset: -6;
    }
  }

  .erp-root .about-draw > *,.erp-root 
  .about-trace {
    stroke-dasharray: 1;
    stroke-dashoffset: 0;
    animation: 6s ease-in-out infinite;
    animation-name: var(--a-draw, none);
    animation-delay: calc(var(--i, 0) * 0.4s);
  }

  .erp-root .about-trace {
    animation-duration: 7s;
  }

  @keyframes about-draw {
    0% {
      stroke-dashoffset: 1;
    }

    30%,
    88% {
      stroke-dashoffset: 0;
    }

    100% {
      stroke-dashoffset: 1;
    }
  }

  .erp-root .about-token {
    animation: 4s infinite;
    animation-name: var(--a-token, none);
    animation-delay: calc(var(--i, 0) * 0.5s);
  }

  @keyframes about-token {
    0%,
    12% {
      fill: var(--about-erpai);
      fill-opacity: 1;
    }

    18%,
    100% {
      fill: var(--foreground);
      fill-opacity: 0.85;
    }
  }

  .erp-root .about-bar {
    transform-box: fill-box;
    transform-origin: left center;
    animation: 6s ease-out infinite;
    animation-name: var(--a-bar, none);
    animation-delay: calc(var(--i, 0) * 0.3s);
  }

  @keyframes about-bar {
    0% {
      transform: scaleX(0);
    }

    30%,
    88% {
      transform: scaleX(1);
    }

    100% {
      transform: scaleX(0);
    }
  }

  .erp-root .about-stamp-ink {
    transform-box: fill-box;
