  .erp-root .tacet-about-page .dive--offstage .dive__level {
    --a-sway: none;
    --a-step: none;
    --a-log: none;
    --a-mark: none;
    --a-channel: none;
    --a-flow: none;
    --a-draw: none;
    --a-token: none;
