    .about-step,.erp-root 
    .about-logline,.erp-root 
    .about-mark,.erp-root 
    .about-hex,.erp-root 
    .about-flow line,.erp-root 
    .about-draw > *,.erp-root 
    .about-trace,.erp-root 
    .about-token,.erp-root 
    .about-bar,.erp-root 
    .about-stamp-ink,.erp-root 
    .dive--at-p .about-fixed-ring {
