  /* -- Dive ---------------------------------------------------------------
     A sticky stage draws the recursive figure; the chapters in the track
     scroll over it, and the HUD follows the track as a sticky bar so it stays
     above them. about-droste.js maps scroll to the zoom depth.

     Stacked (narrow and portrait screens): the frame is centred between the
     nav and the HUD bar, and the chapters pass over it. Side by side (wide
     landscape screens): the text column and the frame are centred as a pair,
     with the HUD under the frame. */

  .erp-root .tacet-about-page .dive {
    position: relative;
    margin-top: calc(-1 * var(--chrome-height, 0px));
  }

  .erp-root .tacet-about-page .dive__stage {
    position: sticky;
    top: 0;
    height: 100svh;
    overflow: hidden;
    border-bottom: 1px solid var(--foreground);
    background: var(--background);
  }

  .erp-root .tacet-about-page .dive__frame {
    position: absolute;
    top: calc(var(--dive-nav) + 0.75rem + (var(--dive-avail) - var(--dive-frame-h)) / 2);
    left: 50%;
    height: var(--dive-frame-h);
    aspect-ratio: 4 / 5;
    transform: translateX(-50%);
  }

  .erp-root .tacet-about-page .dive__svg {
    display: block;
    width: 100%;
    height: 100%;
    overflow: visible;
  }

  /* -- HUD ---------------------------------------------------------------- */

  .erp-root .tacet-about-page .dive__hud {
    position: sticky;
    bottom: 0;
    z-index: 2;
    box-sizing: border-box;
    height: var(--dive-hud);
    padding: 0.5rem max(1rem, calc((100% - 30rem) / 2)) 0;
    border-block: 1px solid var(--foreground);
    background: var(--background);
    font-family: var(--font-mono);
    font-size: 0.75rem;
    line-height: 1.4;
    color: var(--text-m);
  }

  .erp-root .tacet-about-page .dive:not(.dive--live) .dive__hud {
    display: none;
  }

  .erp-root .tacet-about-page .dive__readout {
    display: grid;
    grid-template-columns: repeat(3, max-content);
    column-gap: 0.75rem;
    row-gap: 0.125rem;
    margin-bottom: 0.375rem;
  }

  .erp-root .tacet-about-page .dive__pair {
    display: flex;
    align-items: baseline;
    gap: 0.375rem;
    white-space: nowrap;
  }

  .erp-root .tacet-about-page .dive__readout dt {
    color: var(--muted-foreground);
  }

  /* Symbols are set like the maths in the text, so φ reads as phi. */
  .erp-root .tacet-about-page .dive__readout .dive__sym {
