  .erp-root .tacet-about-page .dive__readout dd {
    min-width: 4rem;
    margin: 0;
    font-variant-numeric: tabular-nums;
    color: var(--foreground);
  }

  .erp-root .tacet-about-page .dive__gauge {
    position: relative;
    height: 1.75rem;
    margin-inline: 1.25rem;
  }

  .erp-root .tacet-about-page .dive__gauge-seg {
    position: absolute;
    top: 0.25rem;
    width: 12.5%;
    height: 0.3125rem;
  }

  .erp-root .tacet-about-page .dive__gauge-seg--at-0 {
    left: 0%;
  }

  .erp-root .tacet-about-page .dive__gauge-seg--at-1 {
    left: 12.5%;
  }

  .erp-root .tacet-about-page .dive__gauge-seg--at-2 {
    left: 25%;
  }

  .erp-root .tacet-about-page .dive__gauge-seg--at-3 {
    left: 37.5%;
  }

  .erp-root .tacet-about-page .dive__gauge-seg--at-4 {
    left: 50%;
  }

  .erp-root .tacet-about-page .dive__gauge-seg--at-5 {
    left: 62.5%;
  }

  .erp-root .tacet-about-page .dive__gauge-seg--at-6 {
    left: 75%;
  }

  .erp-root .tacet-about-page .dive__gauge-seg--at-7 {
    left: 87.5%;
  }

  .erp-root .tacet-about-page .dive__gauge-seg--erpai {
    background: var(--about-erpai);
  }

  .erp-root .tacet-about-page .dive__gauge-seg--papa {
    background: var(--about-papa);
  }

  .erp-root .tacet-about-page .dive__gauge-seg--dixit {
    background: var(--about-dixit);
  }

  .erp-root .tacet-about-page .dive__gauge-seg--misra {
    background: var(--about-misra);
  }

  /* The frame and window values carry their level's colour. */
  .erp-root .tacet-about-page .dive__readout dd[data-slug]::before {
    display: inline-block;
    width: 0.625em;
    height: 0.625em;
    margin-right: 0.375em;
    background: var(--about-swatch, transparent);
    content: '';
  }

  .erp-root .tacet-about-page .dive__readout dd[data-slug='erpai'] {
    --about-swatch: var(--about-erpai);
  }

  .erp-root .tacet-about-page .dive__readout dd[data-slug='papa'] {
    --about-swatch: var(--about-papa);
  }

  .erp-root .tacet-about-page .dive__readout dd[data-slug='dixit'] {
    --about-swatch: var(--about-dixit);
  }

  .erp-root .tacet-about-page .dive__readout dd[data-slug='misra'] {
    --about-swatch: var(--about-misra);
  }

  .erp-root .tacet-about-page .dive__gauge-tick {
    position: absolute;
    top: 0;
    padding-top: 0.875rem;
    font-size: 0.625rem;
    line-height: 1;
    color: var(--muted-foreground);
    white-space: nowrap;
    transform: translateX(-50%);
  }

  .erp-root .tacet-about-page .dive__gauge-tick::before {
    position: absolute;
    top: 0;
    left: 50%;
    width: 1px;
    height: 0.75rem;
    background: var(--foreground);
    content: '';
  }

  .erp-root .tacet-about-page .dive__gauge-tick--0 {
    left: 0%;
  }

  .erp-root .tacet-about-page .dive__gauge-tick--1 {
    left: 12.5%;
  }

  .erp-root .tacet-about-page .dive__gauge-tick--2 {
    left: 25%;
  }

  .erp-root .tacet-about-page .dive__gauge-tick--3 {
    left: 37.5%;
  }

  .erp-root .tacet-about-page .dive__gauge-tick--4 {
    left: 50%;
  }

  .erp-root .tacet-about-page .dive__gauge-tick--5 {
    left: 62.5%;
  }

  .erp-root .tacet-about-page .dive__gauge-tick--6 {
    left: 75%;
  }

  .erp-root .tacet-about-page .dive__gauge-tick--7 {
