  /* -- Track and chapters ------------------------------------------------- */

  .erp-root .tacet-about-page .dive__track {
    position: relative;
    z-index: 1;
    display: flow-root;
    margin-top: -100svh;
    padding: calc(var(--dive-nav) + 0.75rem) 1.5rem 0;
  }

  .erp-root .tacet-about-page .dive__chapter {
    max-width: 36rem;
    margin: 0 auto 80svh;
    --about-band: var(--about-erpai);

    padding: 2.25rem 1.5rem 2rem;
    border: 1px solid var(--foreground);
    background: var(--background);
    box-shadow: inset 0 0.5rem 0 var(--about-band);
    container-type: inline-size;
  }

  /* Each panel carries the colour of the level it is read over: the
     people in their own fields, the rest in the cover's orange. */
  .erp-root .tacet-about-page .dive__chapter--papa {
    --about-band: var(--about-papa);
  }

  .erp-root .tacet-about-page .dive__chapter--dixit {
    --about-band: var(--about-dixit);
  }

  .erp-root .tacet-about-page .dive__chapter--misra {
    --about-band: var(--about-misra);
  }

  /* .proto-saas section sets a faint border with !important; every panel in
     the track keeps the same 1px foreground edge. */
  .erp-root .tacet-about-page section.dive__chapter {
    border-color: var(--foreground) !important;
  }

  /* The cover card leaves the frame's window in view on the first screen. */
  .erp-root .tacet-about-page .dive__chapter--cover {
    margin-bottom: 50svh;
  }

  .erp-root .tacet-about-page .dive__chapter--intro {
    margin-bottom: 40svh;
  }

  /* After the loop the dive falls through one more turn of the cycle with no
     text over it, and lands on the cover at the last chapter. */
  .erp-root .tacet-about-page .dive__chapter--loop {
    margin-bottom: 240svh;
  }

  .erp-root .tacet-about-page .dive__chapter--end {
    margin-bottom: 45svh;
  }

  .erp-root .tacet-about-page .dive__chapter > * + * {
    margin-top: 1rem;
  }

  .erp-root .tacet-about-page .dive__chapter p {
    line-height: 1.6;
    color: var(--foreground);
  }

  .erp-root .tacet-about-page .dive__title {
    font-family: var(--font-heading);
    font-size: clamp(2.75rem, 11vw, 4.5rem);
    font-weight: 700;
    line-height: 0.92;
    color: var(--foreground);
  }

  .erp-root .tacet-about-page .dive__title-accent {
    color: var(--org-on-light);
  }

  .erp-root .tacet-about-page .dive--live .dive__title > span {
    display: inline-block;
    animation: about-rise 900ms var(--ease-out, cubic-bezier(0.2, 0.8, 0.2, 1)) backwards;
  }

  .erp-root .tacet-about-page .dive--live .dive__title > span + span {
    animation-delay: 140ms;
  }

  @keyframes about-rise {
    from {
      opacity: 0;
      translate: 0 0.35em;
    }
  }

  /* Panels rise into place the first time they enter the viewport. */
  .erp-root .tacet-about-page .dive--live .dive__chapter:not(.dive__chapter--cover) > * {
    opacity: 0;
    translate: 0 1rem;
    transition:
      opacity 500ms var(--ease-out, cubic-bezier(0.2, 0.8, 0.2, 1)),
      translate 500ms var(--ease-out, cubic-bezier(0.2, 0.8, 0.2, 1));
  }

  .erp-root .tacet-about-page .dive--live .dive__chapter.is-in > * {
    opacity: 1;
    translate: 0 0;
  }

  .erp-root .tacet-about-page .dive--live .dive__chapter.is-in > :nth-child(2) {
    transition-delay: 70ms;
  }

  .erp-root .tacet-about-page .dive--live .dive__chapter.is-in > :nth-child(3) {
    transition-delay: 140ms;
  }

  .erp-root .tacet-about-page .dive--live .dive__chapter.is-in > :nth-child(n + 4) {
    transition-delay: 210ms;
  }

  @media (prefers-reduced-motion: reduce) {
    .erp-root .tacet-about-page .dive--live .dive__title > span {
      animation: none;
    }

    .erp-root .tacet-about-page .dive--live .dive__chapter:not(.dive__chapter--cover) > * {
      opacity: 1;
      translate: none;
      transition: none;
    }
  }

  .erp-root .tacet-about-page .dive__chapter > .dive__lead {
    margin-top: 1.25rem;
    font-size: 1.0625rem;
    line-height: 1.5;
    color: var(--text-m);
  }

  .erp-root .tacet-about-page .dive__chapter > .dive__hint,.erp-root 
  .tacet-about-page .dive__chapter > .dive__onscreen {
    font-size: 0.9375rem;
    line-height: 1.5;
    color: var(--text-m);
  }

  .erp-root .tacet-about-page .dive__hint-step {
    display: none;
  }

  .erp-root .tacet-about-page .dive--stepped .dive__hint-step {
