  }

  .erp-root .tacet-about-page .dive--stepped .dive__hint-live,.erp-root 
  .tacet-about-page .dive:not(.dive--live) .dive__hint {
    display: none;
  }

  .erp-root .tacet-about-page .dive__chapter > .dive__onscreen {
    margin-top: 1.75rem;
    padding-top: 0.75rem;
    border-top: 1px solid var(--border);
  }

  .erp-root .tacet-about-page .dive__heading {
    font-family: var(--font-heading);
    font-size: 2rem;
    font-weight: 700;
    line-height: 1.1;
    color: var(--foreground);
  }

  .erp-root .tacet-about-page .dive__chapter > .dive__name {
    font-family: var(--font-heading);
    font-size: clamp(2.75rem, 5vw, 4.25rem);
    font-weight: 700;
    line-height: 0.95;
    color: var(--foreground);
  }

  .erp-root .tacet-about-page .dive__chapter > .dive__role {
