  /* -- Side by side ------------------------------------------------------- */

  @media (min-width: 1024px) and (min-aspect-ratio: 1 / 1),
    (max-height: 520px) and (min-aspect-ratio: 1 / 1) {
    /* The frame is as tall as the space allows, but never so tall that the
       text column drops below 28rem; the pair is then centred. */
    .erp-root .tacet-about-page {
      --dive-side-min: max(4vw, 2rem);
      --dive-frame-h: min(
        var(--dive-avail),
        calc((100vw - 2 * var(--dive-side-min) - var(--dive-gap) - 28rem) * 1.25)
      );
      --dive-frame-w: calc(var(--dive-frame-h) * 0.8);
      --dive-text-w: min(
        36rem,
        calc(100vw - 2 * var(--dive-side-min) - var(--dive-gap) - var(--dive-frame-w))
      );
      --dive-side: max(
        var(--dive-side-min),
        calc((100vw - var(--dive-text-w) - var(--dive-gap) - var(--dive-frame-w)) / 2)
      );
    }

    .erp-root .tacet-about-page .dive__frame {
      right: var(--dive-side);
      left: auto;
      transform: none;
    }

    .erp-root .tacet-about-page .dive__hud {
      width: var(--dive-frame-w);
      margin-right: var(--dive-side);
      margin-left: auto;
      padding-inline: 0.75rem;
    }

    .erp-root .tacet-about-page .dive__track {
      padding-top: calc(var(--dive-nav) + 0.75rem + (var(--dive-avail) - var(--dive-frame-h)) / 2);
      padding-right: 0;
      padding-left: var(--dive-side);
    }

    .erp-root .tacet-about-page .dive__chapter {
      width: var(--dive-text-w);
      margin-left: 0;
    }

    /* The cover spans the frame's height: title at its top edge, the hint
       on its bottom edge. */
    .erp-root .tacet-about-page .dive__chapter--cover {
      display: flex;
      flex-direction: column;
      min-height: var(--dive-frame-h);
      margin-bottom: 20svh;
      padding: 0;
      border: 0;
      background: transparent;
      box-shadow: none;
    }

    .erp-root .tacet-about-page .dive__chapter--cover > .dive__hint {
      max-width: 26rem;
      margin-top: auto;
      padding-top: 1.5rem;
    }

    .erp-root .tacet-about-page .dive__title {
      font-size: clamp(3.25rem, 6.5vw, 7.5rem);
    }

    .erp-root .tacet-about-page .dive__chapter > .dive__lead {
      margin-top: 1.5rem;
      font-size: 1.25rem;
    }

    .erp-root .tacet-about-page .about {
      max-width: none;
      padding-inline: var(--dive-side);
    }
  }

  /* Large screens: the instrument grows with the frame. */
  @media (min-width: 1600px) and (min-height: 960px) and (min-aspect-ratio: 1 / 1) {
    .erp-root .tacet-about-page {
      --dive-hud: 6.25rem;
    }

    .erp-root .tacet-about-page .dive__hud {
