  .erp-root .container {
    width: 100%;
    max-width: 90rem;
    margin-inline: auto;
    padding-left: max(var(--space-4), var(--viewport-safe-left));
    padding-right: max(var(--space-4), var(--viewport-safe-right));
  }
  @media (min-width: 640px) {
    .erp-root .container {
      padding-left: max(var(--space-6), var(--viewport-safe-left));
      padding-right: max(var(--space-6), var(--viewport-safe-right));
    }
  }
  @media (min-width: 1024px) {
    .erp-root .container {
      padding-left: max(var(--space-8), var(--viewport-safe-left));
      padding-right: max(var(--space-8), var(--viewport-safe-right));
    }
  }

  @media (max-width: 63.99rem) {
    .erp-root .erpai-hero__column {
      padding-left: max(var(--space-6), var(--viewport-safe-left));
      padding-right: max(var(--space-6), var(--viewport-safe-right));
    }
  }

  .erp-root .container--narrow {
    max-width: 768px;
  }
  .erp-root .container--wide {
    max-width: 1536px;
  }

  .erp-root .section {
    padding-block: var(--space-16);
  }
  .erp-root .section--sm {
    padding-block: var(--space-8);
  }
  .erp-root .section--lg {
    padding-block: var(--space-24);
  }

  .erp-root .flex-center {
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .erp-root .flex-between {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  /* `flex-stack` (not `flex-col`) — avoids shadowing Tailwind's `.flex-col`
     utility, which would silently break responsive overrides like
     `flex-stack sm:flex-row` because the custom rule (loaded after
     tailwind.css) wins the cascade. Use this single class to get both
     `display: flex` and a column layout. */
  .erp-root .flex-stack {
    display: flex;
    flex-direction: column;
  }

  .erp-root .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border-width: 0;
  }

  .erp-root [data-observe~='stagger'] > * {
    transition-delay: calc(var(--stagger-index, 0) * 80ms);
  }

  .erp-root .choreo-signature [data-line] {
    display: inline-block;
    line-height: inherit;
  }

  .erp-root .choreo-delay-0 {
    --stagger-index: 0;
  }

  .erp-root .choreo-delay-1 {
    --stagger-index: 1;
  }

  .erp-root .choreo-delay-2 {
    --stagger-index: 2;
  }

  .erp-root .choreo-delay-3 {
    --stagger-index: 3;
  }

  .erp-root .choreo-delay-4 {
    --stagger-index: 4;
  }

  .erp-root .choreo-delay-5 {
    --stagger-index: 5;
  }

  .erp-root .choreo-delay-6 {
    --stagger-index: 6;
  }

  .erp-root .choreo-delay-7 {
    --stagger-index: 7;
  }

  @media (prefers-reduced-motion: no-preference) {
    .erp-root .choreo-reveal {
      opacity: 0;
      transform: translateY(16px);
      animation: choreo-rise var(--duration-signature) var(--ease-signature) both;
      animation-delay: calc(var(--stagger-index, 0) * 80ms);
    }

    .erp-root .choreo-signature [data-line] {
      opacity: 0;
      clip-path: inset(-0.06em 0 100% 0);
      transform: translateY(0.18em);
      animation: choreo-signature-rise var(--duration-signature) var(--ease-signature) both;
      animation-delay: calc(var(--stagger-index, 0) * 80ms);
    }
  }

  @keyframes choreo-rise {
    from {
      opacity: 0;
      transform: translateY(16px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes choreo-signature-rise {
    from {
      opacity: 0;
      clip-path: inset(-0.06em 0 100% 0);
      transform: translateY(0.18em);
    }
    to {
      opacity: 1;
      clip-path: inset(-0.06em 0 -0.16em 0);
      transform: translateY(0);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .erp-root .choreo-reveal,.erp-root 
    .choreo-signature [data-line] {
      opacity: 1;
      clip-path: none;
      transform: none;
      animation: none;
    }
  }

  /* Mark highlights — gradient underline emphasis */
  .erp-root .mark-ylw {
    background: linear-gradient(
      104deg,
      transparent 0.9%,
      rgb(255, 225, 53, 0.3) 2.4%,
      rgb(255, 225, 53, 0.5) 5.8%,
      rgb(255, 225, 53, 0.15) 93%,
      rgb(255, 225, 53, 0.4) 96%,
      transparent 98%
    );
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
    padding: 0 2px;
  }
  .erp-root .mark-red {
    background: linear-gradient(
      104deg,
      transparent 0.9%,
      rgb(232, 66, 48, 0.25) 2.4%,
      rgb(232, 66, 48, 0.4) 5.8%,
      rgb(232, 66, 48, 0.12) 93%,
      rgb(232, 66, 48, 0.35) 96%,
      transparent 98%
    );
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
    padding: 0 2px;
  }
