@media (prefers-reduced-motion: reduce) {
  .erp-root *,.erp-root 
  *::before,.erp-root 
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
@media (prefers-reduced-motion: reduce) {
  .erp-root [data-observe~='draw-path'] path[data-draw],.erp-root 
  [data-observe~='draw-path'].observed path[data-draw] {
    transition: none !important;
    stroke-dashoffset: 0 !important;
    stroke-dasharray: none !important;
  }
  .erp-root [data-observe~='signature-reveal'] [data-line],.erp-root 
  [data-observe~='signature-reveal'].observed [data-line] {
    animation: none !important;
    clip-path: inset(0 0 0 0) !important;
    transform: none !important;
    opacity: 1 !important;
    will-change: auto;
  }
